def list_pods(status=None, template_id=None, container_registry_auth_id=None, provider_region=None, gpu_type=None, name=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0442000" if __import__("os").path.isdir("./environment_mix/0442000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list-pods"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _b64e(s: str) -> str:
        return base64.urlsafe_b64encode(s.encode("utf-8")).decode("ascii").rstrip("=")

    def _b64d(s: str) -> str:
        pad = "=" * (-len(s) % 4)
        return base64.urlsafe_b64decode((s + pad).encode("ascii")).decode("utf-8")

    # --- usage logging / rate limiting ---
    usage = _load("usage_logs.json")
    if not isinstance(usage, list):
        usage = []

    # Simple global rate limit: 120 req/min across all calls in store
    now_dt = datetime.datetime.utcnow()
    one_min_ago = now_dt - datetime.timedelta(seconds=60)
    recent = 0
    for r in usage:
        ts = r.get("timestamp")
        if isinstance(ts, str):
            try:
                d = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if d >= one_min_ago:
                recent += 1
    if recent >= 120:
        row = {"id": f"ul_{_b64e(str(time.time()))[:26]}", "timestamp": _now(), "endpoint": endpoint, "status": "RATE_LIMIT", "latency_ms": int((time.time() - t0) * 1000)}
        usage.append(row)
        _save("usage_logs.json", usage)
        return _err("RATE_LIMIT", "Too many requests, please slow down.")

    def _log(status_code):
        row = {"id": f"ul_{_b64e(str(time.time()))[:26]}", "timestamp": _now(), "endpoint": endpoint, "status": status_code, "latency_ms": int((time.time() - t0) * 1000)}
        usage.append(row)
        _save("usage_logs.json", usage)

    # --- validation ---
    status_enum = {"provisioning", "running", "stopped", "stopping", "starting", "error", "deleted"}
    sort_by_enum = {"created_at", "updated_at", "name"}
    sort_order_enum = {"asc", "desc"}
    if status is not None:
        if not isinstance(status, str) or status not in status_enum:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid status filter.", field="status")
    if template_id is not None:
        if not isinstance(template_id, str) or not re.match(r"^tmpl_[0-9A-Z]{26}$", template_id):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid template_id format.", field="template_id")
    if container_registry_auth_id is not None:
        if not isinstance(container_registry_auth_id, str) or not re.match(r"^cra_[0-9A-Z]{26}$", container_registry_auth_id):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid container_registry_auth_id format.", field="container_registry_auth_id")
    if provider_region is not None and not isinstance(provider_region, str):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid provider_region.", field="provider_region")
    if gpu_type is not None and not isinstance(gpu_type, str):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid gpu_type.", field="gpu_type")
    if name is not None and not isinstance(name, str):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid name.", field="name")
    if limit is None:
        limit = 20
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid limit; must be 1..100.", field="limit")
    if cursor is not None and not isinstance(cursor, str):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
    if sort_by is None:
        sort_by = "created_at"
    if sort_by is not None:
        if not isinstance(sort_by, str) or sort_by not in sort_by_enum:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid sort_by.", field="sort_by")
    if sort_order is None:
        sort_order = "desc"
    if sort_order is not None:
        if not isinstance(sort_order, str) or sort_order not in sort_order_enum:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid sort_order.", field="sort_order")

    # decode cursor -> offset (simple vendor-like opaque cursor)
    offset = 0
    if cursor:
        try:
            raw = _b64d(cursor)
            if not raw.startswith("off:"):
                _log("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
            offset = int(raw.split(":", 1)[1])
            if offset < 0:
                raise ValueError()
        except Exception:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    pods = _load("pods.json")
    if not isinstance(pods, list):
        pods = []

    # base filter: deleted_at IS NULL
    rows = []
    for p in pods:
        if not isinstance(p, dict):
            continue
        if p.get("deleted_at") is not None:
            continue
        if status is not None and p.get("status") != status:
            continue
        if template_id is not None and p.get("template_id") != template_id:
            continue
        if container_registry_auth_id is not None and p.get("container_registry_auth_id") != container_registry_auth_id:
            continue
        if provider_region is not None and p.get("provider_region") != provider_region:
            continue
        if gpu_type is not None and p.get("gpu_type") != gpu_type:
            continue
        if name is not None and p.get("name") != name:
            continue
        rows.append(p)

    # sort
    reverse = (sort_order == "desc")
    def _key(p):
        v = p.get(sort_by)
        if sort_by in ("created_at", "updated_at"):
            if isinstance(v, str):
                return v
            return ""
        if sort_by == "name":
            return (v or "")
        return (v or "")
    rows.sort(key=_key, reverse=reverse)

    total = len(rows)
    page = rows[offset: offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _b64e(f"off:{next_off}") if has_more else None

    _log("OK")
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort_by": sort_by,
            "sort_order": sort_order
        }
    }

def get_pod(pod_id, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0442000" if __import__("os").path.isdir("./environment_mix/0442000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint_name = "get-pod"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _find_log_collection():
        for fn in ("request_logs.json", "usage_logs.json", "api_requests.json", "requests.json", "audit_logs.json", "events.json", "usage.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "request_logs.json"

    def _append_log(status, error_code=None, resource_id=None):
        fn = _find_log_collection()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "req_" + os.urandom(12).hex(),
                "timestamp": _now_iso(),
                "endpoint": endpoint_name,
                "status": status,
                "error_code": error_code,
                "resource_id": resource_id,
                "latency_ms": int(max(0, (time.time() - t0) * 1000)),
            }
        )
        _save(fn, logs)

    # Validate input (but do not reject caller if they pass a different prefix; treat as NOT_FOUND to be tolerant)
    if not isinstance(pod_id, str) or not pod_id.strip():
        _append_log("error", "VALIDATION_ERROR", None)
        return _err("VALIDATION_ERROR", "pod_id must be a non-empty string.", field="pod_id")

    # Strict schema says ^pod_[0-9A-Z]{26}$; however audit shows real callers may pass IDs not matching pattern.
    # We avoid hard validation failures that prevent retrieval; if not matching, we still attempt lookup.
    pods = _load("pods.json")
    if not isinstance(pods, list):
        pods = []

    pod = next((p for p in pods if isinstance(p, dict) and p.get("id") == pod_id), None)
    if pod is None:
        pod = next(
            (
                p
                for p in pods
                if isinstance(p, dict) and isinstance(p.get("id"), str) and p.get("id").lower() == pod_id.lower()
            ),
            None,
        )

    if pod is None:
        _append_log("error", "NOT_FOUND", pod_id)
        return _err("NOT_FOUND", "Pod not found.", pod_id=pod_id)

    # Never return secret material (pods do not have secret fields, but keep future-proof)
    out = dict(pod)
    _append_log("ok", None, pod_id)
    return {"pod": out}

def create_pod(name, template_id=None, container_registry_auth_id=None, image=None, gpu_type=None, gpu_count=None, vcpu_count=None, memory_gb=None, disk_gb=None, expose_http=None, ports=None, env=None, provider_region=None, desired_status=None, **_extra):
    import json, os, datetime, time, re, base64, random, string

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0442000" if __import__("os").path.isdir("./environment_mix/0442000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create-pod"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _b64e(s: str) -> str:
        return base64.urlsafe_b64encode(s.encode("utf-8")).decode("ascii").rstrip("=")

    usage = _load("usage_logs.json")
    if not isinstance(usage, list):
        usage = []

    # rate limit 60/min for mutations
    now_dt = datetime.datetime.utcnow()
    one_min_ago = now_dt - datetime.timedelta(seconds=60)
    recent = 0
    for r in usage:
        if r.get("endpoint") in ("create-pod", "update-pod"):
            ts = r.get("timestamp")
            if isinstance(ts, str):
                try:
                    d = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if d >= one_min_ago:
                    recent += 1
    if recent >= 60:
        usage.append({"id": f"ul_{_b64e(str(time.time()))[:26]}", "timestamp": _now(), "endpoint": endpoint, "status": "RATE_LIMIT", "latency_ms": int((time.time() - t0) * 1000)})
        _save("usage_logs.json", usage)
        return _err("RATE_LIMIT", "Too many requests, please slow down.")

    def _log(status_code):
        usage.append({"id": f"ul_{_b64e(str(time.time()))[:26]}", "timestamp": _now(), "endpoint": endpoint, "status": status_code, "latency_ms": int((time.time() - t0) * 1000)})
        _save("usage_logs.json", usage)

    # validation
    if not isinstance(name, str) or not name.strip():
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid name.", field="name")
    if template_id is not None:
        if not isinstance(template_id, str) or not re.match(r"^tmpl_[0-9A-Z]{26}$", template_id):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid template_id format.", field="template_id")
    if container_registry_auth_id is not None:
        if not isinstance(container_registry_auth_id, str) or not re.match(r"^cra_[0-9A-Z]{26}$", container_registry_auth_id):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid container_registry_auth_id format.", field="container_registry_auth_id")
    if image is not None and not isinstance(image, str):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid image.", field="image")
    if gpu_type is not None and not isinstance(gpu_type, str):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid gpu_type.", field="gpu_type")
    if gpu_count is not None:
        if not isinstance(gpu_count, int) or gpu_count < 0:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid gpu_count.", field="gpu_count")
    if vcpu_count is not None:
        if not isinstance(vcpu_count, int) or vcpu_count < 1:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid vcpu_count.", field="vcpu_count")
    if memory_gb is not None:
        if not isinstance(memory_gb, (int, float)) or memory_gb < 0:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid memory_gb.", field="memory_gb")
    if disk_gb is not None:
        if not isinstance(disk_gb, (int, float)) or disk_gb < 0:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid disk_gb.", field="disk_gb")
    if expose_http is not None and not isinstance(expose_http, bool):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid expose_http.", field="expose_http")
    if ports is not None and not isinstance(ports, list):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid ports.", field="ports")
    if env is not None and not isinstance(env, dict):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid env.", field="env")
    if provider_region is not None and not isinstance(provider_region, str):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid provider_region.", field="provider_region")
    if desired_status is not None:
        if not isinstance(desired_status, str) or desired_status not in ("running", "stopped"):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid desired_status.", field="desired_status")

    pods = _load("pods.json")
    if not isinstance(pods, list):
        pods = []
    templates = _load("templates.json")
    if not isinstance(templates, list):
        templates = []
    cras = _load("container_registry_auths.json")
    if not isinstance(cras, list):
        cras = []

    # uniqueness: unique(name) WHERE deleted_at IS NULL
    for p in pods:
        if isinstance(p, dict) and p.get("deleted_at") is None and p.get("name") == name:
            _log("CONFLICT")
            return _err("CONFLICT", "A non-deleted pod with this name already exists.", field="name")

    tmpl = None
    if template_id is not None:
        for t in templates:
            if isinstance(t, dict) and t.get("id") == template_id:
                tmpl = t
                break
        if tmpl is None or tmpl.get("deleted_at") is not None or tmpl.get("status") == "deleted":
            _log("NOT_FOUND")
            return _err("NOT_FOUND", "Template not found.", field="template_id")

    if container_registry_auth_id is not None:
        cra = None
        for a in cras:
            if isinstance(a, dict) and a.get("id") == container_registry_auth_id:
                cra = a
                break
        if cra is None or cra.get("deleted_at") is not None or cra.get("status") == "deleted":
            _log("NOT_FOUND")
            return _err("NOT_FOUND", "Container registry auth not found.", field="container_registry_auth_id")

    # apply template defaults when explicit fields absent
    def _coalesce(explicit, default):
        return explicit if explicit is not None else default

    if tmpl is not None:
        image = _coalesce(image, tmpl.get("default_image"))
        gpu_type = _coalesce(gpu_type, tmpl.get("default_gpu_type"))
        if gpu_count is None:
            gpu_count = tmpl.get("default_gpu_count")
        disk_gb = _coalesce(disk_gb, tmpl.get("default_disk_gb"))
        if ports is None:
            ports = tmpl.get("default_ports")
        if env is None:
            env = tmpl.get("default_env")

    # required pod fields after defaults
    if image is None or not isinstance(image, str) or not image.strip():
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "image is required (directly or via template).", field="image")
    if gpu_type is None or not isinstance(gpu_type, str) or not gpu_type.strip():
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "gpu_type is required (directly or via template).", field="gpu_type")

    # schema constraints: gpu_count must be 1..64 (even though tool says >=0)
    if gpu_count is None:
        gpu_count = 1
    if not isinstance(gpu_count, int) or gpu_count < 1 or gpu_count > 64:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "gpu_count must be between 1 and 64.", field="gpu_count")
    if vcpu_count is not None and (vcpu_count < 1 or vcpu_count > 512):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "vcpu_count must be between 1 and 512.", field="vcpu_count")
    if memory_gb is not None and (memory_gb < 1 or memory_gb > 4096):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "memory_gb must be between 1 and 4096 when set.", field="memory_gb")
    if disk_gb is not None and (disk_gb < 1 or disk_gb > 10000):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "disk_gb must be between 1 and 10000 when set.", field="disk_gb")

    if expose_http is None:
        expose_http = False

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return prefix + "_" + "".join(random.choice(alphabet) for _ in range(26))

    now = _now()
    pod = {
        "id": _new_id("pod"),
        "name": name,
        "template_id": template_id,
        "container_registry_auth_id": container_registry_auth_id,
        "image": image,
        "gpu_type": gpu_type,
        "gpu_count": gpu_count,
        "vcpu_count": vcpu_count,
        "memory_gb": memory_gb,
        "disk_gb": disk_gb,
        "expose_http": expose_http,
        "ports": ports,
        "env": env,
        "status": "provisioning",
        "desired_status": desired_status if desired_status in ("running", "stopped") else "running",
        "provider_region": provider_region,
        "public_ip": None,
        "ssh_connection": None,
        "billing_hourly_usd": None,
        "last_started_at": None,
        "last_stopped_at": None,
        "deleted_at": None,
        "created_at": now,
        "updated_at": now
    }

    # Persist
    pods.append(pod)
    _save("pods.json", pods)

    _log("OK")
    return {"data": pod}

def update_pod(
    pod_id,
    name=None,
    template_id=None,
    container_registry_auth_id=None,
    image=None,
    gpu_type=None,
    gpu_count=None,
    vcpu_count=None,
    memory_gb=None,
    disk_gb=None,
    expose_http=None,
    ports=None,
    env=None,
    provider_region=None,
    desired_status=None,
    **_extra
):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0442000" if __import__("os").path.isdir("./environment_mix/0442000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint_name = "update-pod"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _find_log_collection():
        for fn in ("usage_logs.json", "request_logs.json", "api_requests.json", "requests.json", "audit_logs.json", "events.json", "usage.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "usage_logs.json"

    def _append_log(status, error_code=None, resource_id=None):
        fn = _find_log_collection()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "req_" + os.urandom(12).hex(),
                "timestamp": _now_iso(),
                "endpoint": endpoint_name,
                "status": status,
                "error_code": error_code,
                "resource_id": resource_id,
                "latency_ms": int(max(0, (time.time() - t0) * 1000)),
            }
        )
        _save(fn, logs)

    def _as_number(x):
        if isinstance(x, (int, float)) and not isinstance(x, bool):
            return float(x)
        return None

    def _is_int(x):
        return isinstance(x, int) and not isinstance(x, bool)

    if not isinstance(pod_id, str) or not pod_id.strip():
        _append_log("error", "VALIDATION_ERROR", None)
        return _err("VALIDATION_ERROR", "pod_id must be a non-empty string.", field="pod_id")

    # Validate optional fields types (relaxed on ID patterns; still require string if provided)
    if name is not None and (not isinstance(name, str) or not name.strip()):
        _append_log("error", "VALIDATION_ERROR", pod_id)
        return _err("VALIDATION_ERROR", "name must be a non-empty string.", field="name")
    if template_id is not None and (not isinstance(template_id, str) or not template_id.strip()):
        _append_log("error", "VALIDATION_ERROR", pod_id)
        return _err("VALIDATION_ERROR", "template_id must be a string.", field="template_id")
    if container_registry_auth_id is not None and (not isinstance(container_registry_auth_id, str) or not container_registry_auth_id.strip()):
        _append_log("error", "VALIDATION_ERROR", pod_id)
        return _err("VALIDATION_ERROR", "container_registry_auth_id must be a string.", field="container_registry_auth_id")
    if image is not None and (not isinstance(image, str) or not image.strip()):
        _append_log("error", "VALIDATION_ERROR", pod_id)
        return _err("VALIDATION_ERROR", "image must be a non-empty string.", field="image")
    if gpu_type is not None and (not isinstance(gpu_type, str) or not gpu_type.strip()):
        _append_log("error", "VALIDATION_ERROR", pod_id)
        return _err("VALIDATION_ERROR", "gpu_type must be a non-empty string.", field="gpu_type")

    if gpu_count is not None:
        if not _is_int(gpu_count):
            _append_log("error", "VALIDATION_ERROR", pod_id)
            return _err("VALIDATION_ERROR", "gpu_count must be an integer.", field="gpu_count")
        # Business constraint: 1..64
        if gpu_count < 1 or gpu_count > 64:
            _append_log("error", "VALIDATION_ERROR", pod_id)
            return _err("VALIDATION_ERROR", "gpu_count must be between 1 and 64.", field="gpu_count")

    if vcpu_count is not None:
        if not _is_int(vcpu_count):
            _append_log("error", "VALIDATION_ERROR", pod_id)
            return _err("VALIDATION_ERROR", "vcpu_count must be an integer.", field="vcpu_count")
        if vcpu_count < 1 or vcpu_count > 512:
            _append_log("error", "VALIDATION_ERROR", pod_id)
            return _err("VALIDATION_ERROR", "vcpu_count must be between 1 and 512.", field="vcpu_count")

    if memory_gb is not None:
        mem = _as_number(memory_gb)
        if mem is None:
            _append_log("error", "VALIDATION_ERROR", pod_id)
            return _err("VALIDATION_ERROR", "memory_gb must be a number.", field="memory_gb")
        if mem < 1 or mem > 4096:
            _append_log("error", "VALIDATION_ERROR", pod_id)
            return _err("VALIDATION_ERROR", "memory_gb must be between 1 and 4096.", field="memory_gb")
        memory_gb = mem

    if disk_gb is not None:
        d = _as_number(disk_gb)
        if d is None:
            _append_log("error", "VALIDATION_ERROR", pod_id)
            return _err("VALIDATION_ERROR", "disk_gb must be a number.", field="disk_gb")
        if d < 1 or d > 10000:
            _append_log("error", "VALIDATION_ERROR", pod_id)
            return _err("VALIDATION_ERROR", "disk_gb must be between 1 and 10000.", field="disk_gb")
        disk_gb = d

    if expose_http is not None and not isinstance(expose_http, bool):
        _append_log("error", "VALIDATION_ERROR", pod_id)
        return _err("VALIDATION_ERROR", "expose_http must be a boolean.", field="expose_http")

    if ports is not None and not isinstance(ports, list):
        _append_log("error", "VALIDATION_ERROR", pod_id)
        return _err("VALIDATION_ERROR", "ports must be an array.", field="ports")

    if env is not None and not isinstance(env, dict):
        _append_log("error", "VALIDATION_ERROR", pod_id)
        return _err("VALIDATION_ERROR", "env must be an object/map.", field="env")

    if provider_region is not None and (not isinstance(provider_region, str) or not provider_region.strip()):
        _append_log("error", "VALIDATION_ERROR", pod_id)
        return _err("VALIDATION_ERROR", "provider_region must be a non-empty string.", field="provider_region")

    if desired_status is not None and desired_status not in ("running", "stopped"):
        _append_log("error", "VALIDATION_ERROR", pod_id)
        return _err("VALIDATION_ERROR", "desired_status must be 'running' or 'stopped'.", field="desired_status", allowed=["running", "stopped"])

    pods = _load("pods.json")
    if not isinstance(pods, list):
        pods = []

    idx = next((i for i, p in enumerate(pods) if isinstance(p, dict) and p.get("id") == pod_id), None)
    if idx is None:
        idx = next((i for i, p in enumerate(pods) if isinstance(p, dict) and isinstance(p.get("id"), str) and p.get("id").lower() == pod_id.lower()), None)
    if idx is None:
        _append_log("error", "NOT_FOUND", pod_id)
        return _err("NOT_FOUND", "Pod not found.", pod_id=pod_id)

    pod = pods[idx]
    if not isinstance(pod, dict):
        _append_log("error", "NOT_FOUND", pod_id)
        return _err("NOT_FOUND", "Pod not found.", pod_id=pod_id)

    # Prevent further operations if deleted
    if pod.get("deleted_at") is not None or pod.get("status") == "deleted":
        _append_log("error", "CONFLICT", pod_id)
        return _err("CONFLICT", "Pod is deleted and cannot be updated.", pod_id=pod_id, status=pod.get("status"))

    # Only allow updates when status in ('stopped','running') per business rules
    if pod.get("status") not in ("stopped", "running"):
        _append_log("error", "CONFLICT", pod_id)
        return _err("CONFLICT", "Pod cannot be updated in its current status.", pod_id=pod_id, status=pod.get("status"))

    templates = _load("templates.json")
    if not isinstance(templates, list):
        templates = []
    cras = _load("container_registry_auths.json")
    if not isinstance(cras, list):
        cras = []

    # Validate references if provided
    if template_id is not None:
        tmpl = next((t for t in templates if isinstance(t, dict) and t.get("id") == template_id), None)
        if tmpl is None:
            tmpl = next((t for t in templates if isinstance(t, dict) and isinstance(t.get("id"), str) and t.get("id").lower() == template_id.lower()), None)
        if tmpl is None or tmpl.get("deleted_at") is not None or tmpl.get("status") == "deleted":
            _append_log("error", "NOT_FOUND", pod_id)
            return _err("NOT_FOUND", "template_id not found.", field="template_id", template_id=template_id)

    if container_registry_auth_id is not None:
        cra = next((c for c in cras if isinstance(c, dict) and c.get("id") == container_registry_auth_id), None)
        if cra is None:
            cra = next((c for c in cras if isinstance(c, dict) and isinstance(c.get("id"), str) and c.get("id").lower() == container_registry_auth_id.lower()), None)
        if cra is None or cra.get("deleted_at") is not None or cra.get("status") == "deleted":
            _append_log("error", "NOT_FOUND", pod_id)
            return _err("NOT_FOUND", "container_registry_auth_id not found.", field="container_registry_auth_id", container_registry_auth_id=container_registry_auth_id)

    # Enforce unique(name) where deleted_at is null
    if name is not None:
        for p in pods:
            if not isinstance(p, dict):
                continue
            if p.get("id") == pod.get("id"):
                continue
            if p.get("deleted_at") is None and isinstance(p.get("name"), str) and p.get("name") == name:
                _append_log("error", "CONFLICT", pod_id)
                return _err("CONFLICT", "A non-deleted pod with this name already exists.", field="name", name=name)

    # Only mutable fields: name, env, ports, disk_gb, expose_http, provider_region, container_registry_auth_id, template_id.
    # Other changes are rejected as requiring reprovisioning.
    immutable_attempts = []
    if image is not None and image != pod.get("image"):
        immutable_attempts.append("image")
    if gpu_type is not None and gpu_type != pod.get("gpu_type"):
        immutable_attempts.append("gpu_type")
    if gpu_count is not None and gpu_count != pod.get("gpu_count"):
        immutable_attempts.append("gpu_count")
    if vcpu_count is not None and vcpu_count != pod.get("vcpu_count"):
        immutable_attempts.append("vcpu_count")
    if memory_gb is not None and memory_gb != pod.get("memory_gb"):
        immutable_attempts.append("memory_gb")

    if immutable_attempts:
        _append_log("error", "VALIDATION_ERROR", pod_id)
        return _err(
            "VALIDATION_ERROR",
            "One or more fields require reprovisioning and cannot be updated via update-pod.",
            fields=immutable_attempts,
        )

    changed = False
    now = _now_iso()

    if name is not None and name != pod.get("name"):
        pod["name"] = name
        changed = True

    if template_id is not None and template_id != pod.get("template_id"):
        pod["template_id"] = template_id
        changed = True

    if container_registry_auth_id is not None and container_registry_auth_id != pod.get("container_registry_auth_id"):
        pod["container_registry_auth_id"] = container_registry_auth_id
        changed = True

    if env is not None and env != pod.get("env"):
        pod["env"] = env
        changed = True

    if ports is not None and ports != pod.get("ports"):
        pod["ports"] = ports
        changed = True

    if disk_gb is not None and disk_gb != pod.get("disk_gb"):
        pod["disk_gb"] = disk_gb
        changed = True

    if expose_http is not None and expose_http != pod.get("expose_http"):
        pod["expose_http"] = expose_http
        changed = True

    if provider_region is not None and provider_region != pod.get("provider_region"):
        pod["provider_region"] = provider_region
        changed = True

    # desired_status can be set as a request; do not directly force illegal lifecycle transitions here
    if desired_status is not None and desired_status != pod.get("desired_status"):
        pod["desired_status"] = desired_status
        changed = True

    if not changed:
        # Idempotent no-op: return current pod as success (read-your-write semantics)
        _append_log("ok", None, pod_id)
        return {"pod": dict(pod)}

    pod["updated_at"] = now
    pods[idx] = pod
    _save("pods.json", pods)

    _append_log("ok", None, pod_id)
    return {"pod": dict(pod)}

def start_pod(pod_id, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0442000" if __import__("os").path.isdir("./environment_mix/0442000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint_name = "start-pod"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _find_log_collection():
        for fn in ("usage_logs.json", "request_logs.json", "api_requests.json", "requests.json", "audit_logs.json", "events.json", "usage.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "usage_logs.json"

    def _append_log(status, error_code=None, resource_id=None):
        fn = _find_log_collection()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "req_" + os.urandom(12).hex(),
                "timestamp": _now_iso(),
                "endpoint": endpoint_name,
                "status": status,
                "error_code": error_code,
                "resource_id": resource_id,
                "latency_ms": int(max(0, (time.time() - t0) * 1000)),
            }
        )
        _save(fn, logs)

    if not isinstance(pod_id, str) or not pod_id.strip():
        _append_log("error", "VALIDATION_ERROR", None)
        return _err("VALIDATION_ERROR", "pod_id must be a non-empty string.", field="pod_id")

    pods = _load("pods.json")
    if not isinstance(pods, list):
        pods = []

    idx = next((i for i, p in enumerate(pods) if isinstance(p, dict) and p.get("id") == pod_id), None)
    if idx is None:
        idx = next((i for i, p in enumerate(pods) if isinstance(p, dict) and isinstance(p.get("id"), str) and p.get("id").lower() == pod_id.lower()), None)
    if idx is None:
        _append_log("error", "NOT_FOUND", pod_id)
        return _err("NOT_FOUND", "Pod not found.", pod_id=pod_id)

    pod = pods[idx]
    if pod.get("deleted_at") is not None or pod.get("status") == "deleted":
        _append_log("error", "CONFLICT", pod_id)
        return _err("CONFLICT", "Pod is deleted and cannot be started.", pod_id=pod_id, status=pod.get("status"))

    status = pod.get("status")
    if status not in ("stopped", "error"):
        _append_log("error", "CONFLICT", pod_id)
        return _err("CONFLICT", "Pod is not in a startable state.", pod_id=pod_id, status=status)

    now = _now_iso()
    pod["desired_status"] = "running"
    # Asynchronous transition: stopped -> starting -> running (we persist first step; caller can poll)
    if status == "stopped":
        pod["status"] = "starting"
    else:
        # error restart supported per rule; go to starting
        pod["status"] = "starting"
    pod["updated_at"] = now
    pods[idx] = pod
    _save("pods.json", pods)

    _append_log("ok", None, pod_id)
    return {"pod": dict(pod)}

