def delete_pod(pod_id, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0442000" if __import__("os").path.isdir("./environment_mix/0442000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint_name = "delete-pod"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _find_log_collection():
        for fn in ("usage_logs.json", "request_logs.json", "api_requests.json", "requests.json", "audit_logs.json", "events.json", "usage.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "usage_logs.json"

    def _append_log(status, error_code=None, resource_id=None):
        fn = _find_log_collection()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "req_" + os.urandom(12).hex(),
                "timestamp": _now_iso(),
                "endpoint": endpoint_name,
                "status": status,
                "error_code": error_code,
                "resource_id": resource_id,
                "latency_ms": int(max(0, (time.time() - t0) * 1000)),
            }
        )
        _save(fn, logs)

    if not isinstance(pod_id, str) or not pod_id.strip():
        _append_log("error", "VALIDATION_ERROR", None)
        return _err("VALIDATION_ERROR", "pod_id must be a non-empty string.", field="pod_id")

    pods = _load("pods.json")
    if not isinstance(pods, list):
        pods = []

    idx = next((i for i, p in enumerate(pods) if isinstance(p, dict) and p.get("id") == pod_id), None)
    if idx is None:
        idx = next((i for i, p in enumerate(pods) if isinstance(p, dict) and isinstance(p.get("id"), str) and p.get("id").lower() == pod_id.lower()), None)
    if idx is None:
        _append_log("error", "NOT_FOUND", pod_id)
        return _err("NOT_FOUND", "Pod not found.", pod_id=pod_id)

    pod = pods[idx]
    if pod.get("status") == "deleted" or pod.get("deleted_at") is not None:
        _append_log("error", "INVALID_TRANSITION", pod_id)
        return _err("INVALID_TRANSITION", "Pod is already deleted.", pod_id=pod_id)

    # Detach any network volume mounts referencing this pod before deletion completes
    vols = _load("network_volumes.json")
    if not isinstance(vols, list):
        vols = []

    now = _now_iso()
    vols_changed = False
    for i, v in enumerate(vols):
        if not isinstance(v, dict):
            continue
        mounts = v.get("mounts")
        if not isinstance(mounts, list) or not mounts:
            continue
        new_mounts = [m for m in mounts if not (isinstance(m, dict) and m.get("pod_id") == pod.get("id"))]
        if len(new_mounts) != len(mounts):
            v["mounts"] = new_mounts if new_mounts else []
            # update volume status if it was in_use but now no mounts
            if (v.get("status") == "in_use") and (not new_mounts):
                v["status"] = "available"
            v["updated_at"] = now
            vols[i] = v
            vols_changed = True

    if vols_changed:
        _save("network_volumes.json", vols)

    # Soft delete pod
    pod["status"] = "deleted"
    pod["deleted_at"] = now
    pod["updated_at"] = now
    # Once deleted, desired_status should be cleared
    pod["desired_status"] = None
    pods[idx] = pod
    _save("pods.json", pods)

    _append_log("ok", None, pod_id)
    return {"pod": dict(pod)}

def list_endpoints(status=None, template_id=None, container_registry_auth_id=None, gpu_type=None, auth_mode=None, name=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0442000" if __import__("os").path.isdir("./environment_mix/0442000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_s, latency_ms, error_code=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            row = {
                "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                "service": "runpod",
                "endpoint": "list-endpoints",
                "timestamp": _now(),
                "status": status_s,
                "latency_ms": int(latency_ms),
            }
            if error_code:
                row["error_code"] = error_code
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _parse_cursor(c):
        if c is None:
            return None
        if not isinstance(c, str) or c == "":
            return "invalid"
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            if not s.startswith("idx:"):
                return "invalid"
            n = int(s.split(":", 1)[1])
            if n < 0:
                return "invalid"
            return n
        except Exception:
            return "invalid"

    def _make_cursor(i):
        s = f"idx:{i}"
        return base64.urlsafe_b64encode(s.encode("utf-8")).decode("utf-8").rstrip("=")

    t0 = time.time()

    # Validate filters
    if status is not None:
        if not isinstance(status, str) or status not in {"deploying", "active", "updating", "error", "deleted"}:
            resp = _err("VALIDATION_ERROR", "Invalid status filter.", field="status")
            _log("error", (time.time() - t0) * 1000, resp["error"]["code"])
            return resp

    if template_id is not None:
        if not isinstance(template_id, str) or not re.match(r"^tmpl_[0-9A-Z]{26}$", template_id):
            resp = _err("VALIDATION_ERROR", "template_id is malformed.", field="template_id")
            _log("error", (time.time() - t0) * 1000, resp["error"]["code"])
            return resp

    if container_registry_auth_id is not None:
        if not isinstance(container_registry_auth_id, str) or not re.match(r"^cra_[0-9A-Z]{26}$", container_registry_auth_id):
            resp = _err("VALIDATION_ERROR", "container_registry_auth_id is malformed.", field="container_registry_auth_id")
            _log("error", (time.time() - t0) * 1000, resp["error"]["code"])
            return resp

    if gpu_type is not None and not isinstance(gpu_type, str):
        resp = _err("VALIDATION_ERROR", "gpu_type must be a string.", field="gpu_type")
        _log("error", (time.time() - t0) * 1000, resp["error"]["code"])
        return resp

    if auth_mode is not None:
        if not isinstance(auth_mode, str) or auth_mode not in {"none", "api_key"}:
            resp = _err("VALIDATION_ERROR", "Invalid auth_mode filter.", field="auth_mode")
            _log("error", (time.time() - t0) * 1000, resp["error"]["code"])
            return resp

    if name is not None and not isinstance(name, str):
        resp = _err("VALIDATION_ERROR", "name must be a string.", field="name")
        _log("error", (time.time() - t0) * 1000, resp["error"]["code"])
        return resp

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        resp = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.", field="limit")
        _log("error", (time.time() - t0) * 1000, resp["error"]["code"])
        return resp

    if sort_by is None:
        sort_by = "created_at"
    if not isinstance(sort_by, str) or sort_by not in {"created_at", "updated_at", "name"}:
        resp = _err("VALIDATION_ERROR", "Invalid sort_by.", field="sort_by")
        _log("error", (time.time() - t0) * 1000, resp["error"]["code"])
        return resp

    if sort_order is None:
        sort_order = "desc"
    if not isinstance(sort_order, str) or sort_order not in {"asc", "desc"}:
        resp = _err("VALIDATION_ERROR", "Invalid sort_order.", field="sort_order")
        _log("error", (time.time() - t0) * 1000, resp["error"]["code"])
        return resp

    start = _parse_cursor(cursor)
    if start == "invalid":
        resp = _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
        _log("error", (time.time() - t0) * 1000, resp["error"]["code"])
        return resp
    if start is None:
        start = 0

    endpoints = _load("endpoints.json")
    if not isinstance(endpoints, list):
        endpoints = []

    # Apply policy: list-endpoints returns endpoints where deleted_at IS NULL
    rows = []
    for e in endpoints:
        if not isinstance(e, dict):
            continue
        if e.get("deleted_at") is not None:
            continue
        if status is not None and e.get("status") != status:
            continue
        if template_id is not None and e.get("template_id") != template_id:
            continue
        if container_registry_auth_id is not None and e.get("container_registry_auth_id") != container_registry_auth_id:
            continue
        if gpu_type is not None and e.get("gpu_type") != gpu_type:
            continue
        if auth_mode is not None and e.get("auth_mode") != auth_mode:
            continue
        if name is not None and e.get("name") != name:
            continue
        rows.append(e)

    # Sort
    reverse = (sort_order == "desc")

    def _key(v):
        x = v.get(sort_by)
        # Sort None last consistently
        if x is None:
            return (1, "")
        return (0, x)

    try:
        rows.sort(key=_key, reverse=reverse)
    except TypeError:
        # If mixed types or bad timestamps, fall back to string comparison
        def _key2(v):
            x = v.get(sort_by)
            if x is None:
                return (1, "")
            return (0, str(x))
        rows.sort(key=_key2, reverse=reverse)

    total = len(rows)
    if start > total:
        start = total

    page = rows[start:start + limit]
    next_i = start + len(page)
    has_more = next_i < total
    next_cursor = _make_cursor(next_i) if has_more else None

    resp = {
        "endpoints": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort_by": sort_by,
            "sort_order": sort_order,
        },
    }
    _log("ok", (time.time() - t0) * 1000, None)
    return resp

