    min_workers=None,
    max_workers=None,
    idle_timeout_seconds=None,
    env=None,
    auth_mode=None,
    request_schema=None,
    **_extra
):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0442000" if __import__("os").path.isdir("./environment_mix/0442000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint_name = "update-endpoint"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _find_log_collection():
        for fn in ("usage_logs.json", "request_logs.json", "api_requests.json", "requests.json", "audit_logs.json", "events.json", "usage.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "usage_logs.json"

    def _append_log(status, error_code=None, resource_id=None):
        fn = _find_log_collection()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "req_" + os.urandom(12).hex(),
                "timestamp": _now_iso(),
                "endpoint": endpoint_name,
                "status": status,
                "error_code": error_code,
                "resource_id": resource_id,
                "latency_ms": int(max(0, (time.time() - t0) * 1000)),
            }
        )
        _save(fn, logs)

    def _is_int(x):
        return isinstance(x, int) and not isinstance(x, bool)

    if not isinstance(endpoint_id, str) or not endpoint_id.strip():
        _append_log("error", "VALIDATION_ERROR", None)
        return _err("VALIDATION_ERROR", "endpoint_id must be a non-empty string.", field="endpoint_id")

    # Validate optional fields
    if name is not None and (not isinstance(name, str) or not name.strip()):
        _append_log("error", "VALIDATION_ERROR", endpoint_id)
        return _err("VALIDATION_ERROR", "name must be a non-empty string.", field="name")
    if template_id is not None and (not isinstance(template_id, str) or not template_id.strip()):
        _append_log("error", "VALIDATION_ERROR", endpoint_id)
        return _err("VALIDATION_ERROR", "template_id must be a string.", field="template_id")
    if container_registry_auth_id is not None and (not isinstance(container_registry_auth_id, str) or not container_registry_auth_id.strip()):
        _append_log("error", "VALIDATION_ERROR", endpoint_id)
        return _err("VALIDATION_ERROR", "container_registry_auth_id must be a string.", field="container_registry_auth_id")
    if image is not None and (not isinstance(image, str) or not image.strip()):
        _append_log("error", "VALIDATION_ERROR", endpoint_id)
        return _err("VALIDATION_ERROR", "image must be a non-empty string.", field="image")
    if gpu_type is not None and (not isinstance(gpu_type, str) or not gpu_type.strip()):
        _append_log("error", "VALIDATION_ERROR", endpoint_id)
        return _err("VALIDATION_ERROR", "gpu_type must be a non-empty string.", field="gpu_type")
    if min_workers is not None:
        if not _is_int(min_workers) or min_workers < 0 or min_workers > 1000:
            _append_log("error", "VALIDATION_ERROR", endpoint_id)
            return _err("VALIDATION_ERROR", "min_workers must be an integer between 0 and 1000.", field="min_workers")
    if max_workers is not None:
        if not _is_int(max_workers) or max_workers < 0 or max_workers > 1000:
            _append_log("error", "VALIDATION_ERROR", endpoint_id)
            return _err("VALIDATION_ERROR", "max_workers must be an integer between 0 and 1000.", field="max_workers")
    if min_workers is not None and max_workers is not None and max_workers < min_workers:
        _append_log("error", "VALIDATION_ERROR", endpoint_id)
        return _err("VALIDATION_ERROR", "max_workers must be >= min_workers.", field="max_workers")
    if idle_timeout_seconds is not None:
        if not _is_int(idle_timeout_seconds) or idle_timeout_seconds < 0 or idle_timeout_seconds > 86400:
            _append_log("error", "VALIDATION_ERROR", endpoint_id)
            return _err("VALIDATION_ERROR", "idle_timeout_seconds must be an integer between 0 and 86400.", field="idle_timeout_seconds")
    if env is not None and not isinstance(env, dict):
        _append_log("error", "VALIDATION_ERROR", endpoint_id)
        return _err("VALIDATION_ERROR", "env must be an object/map.", field="env")
    if auth_mode is not None and auth_mode not in ("none", "api_key"):
        _append_log("error", "VALIDATION_ERROR", endpoint_id)
        return _err("VALIDATION_ERROR", "auth_mode must be 'none' or 'api_key'.", field="auth_mode", allowed=["none", "api_key"])
    if request_schema is not None and not isinstance(request_schema, dict):
        _append_log("error", "VALIDATION_ERROR", endpoint_id)
        return _err("VALIDATION_ERROR", "request_schema must be an object.", field="request_schema")

    endpoints = _load("endpoints.json")
    if not isinstance(endpoints, list):
        endpoints = []

    idx = next((i for i, e in enumerate(endpoints) if isinstance(e, dict) and e.get("id") == endpoint_id), None)
    if idx is None:
        idx = next((i for i, e in enumerate(endpoints) if isinstance(e, dict) and isinstance(e.get("id"), str) and e.get("id").lower() == endpoint_id.lower()), None)
    if idx is None:
        _append_log("error", "NOT_FOUND", endpoint_id)
        return _err("NOT_FOUND", "Endpoint not found.", endpoint_id=endpoint_id)

    ep = endpoints[idx]
    if ep.get("deleted_at") is not None or ep.get("status") == "deleted":
        _append_log("error", "CONFLICT", endpoint_id)
        return _err("CONFLICT", "Endpoint is deleted and cannot be updated.", endpoint_id=endpoint_id, status=ep.get("status"))

    templates = _load("templates.json")
    if not isinstance(templates, list):
        templates = []
    cras = _load("container_registry_auths.json")
    if not isinstance(cras, list):
        cras = []

    if template_id is not None:
        tmpl = next((t for t in templates if isinstance(t, dict) and t.get("id") == template_id), None)
        if tmpl is None:
            tmpl = next((t for t in templates if isinstance(t, dict) and isinstance(t.get("id"), str) and t.get("id").lower() == template_id.lower()), None)
        if tmpl is None or tmpl.get("deleted_at") is not None or tmpl.get("status") == "deleted":
            _append_log("error", "NOT_FOUND", endpoint_id)
            return _err("NOT_FOUND", "template_id not found.", field="template_id", template_id=template_id)

    if container_registry_auth_id is not None:
        cra = next((c for c in cras if isinstance(c, dict) and c.get("id") == container_registry_auth_id), None)
        if cra is None:
            cra = next((c for c in cras if isinstance(c, dict) and isinstance(c.get("id"), str) and c.get("id").lower() == container_registry_auth_id.lower()), None)
        if cra is None or cra.get("deleted_at") is not None or cra.get("status") == "deleted":
            _append_log("error", "NOT_FOUND", endpoint_id)
            return _err("NOT_FOUND", "container_registry_auth_id not found.", field="container_registry_auth_id", container_registry_auth_id=container_registry_auth_id)

    # unique(name) where not deleted
    if name is not None:
        for other in endpoints:
            if not isinstance(other, dict):
                continue
            if other.get("id") == ep.get("id"):
                continue
            if other.get("deleted_at") is None and isinstance(other.get("name"), str) and other.get("name") == name:
                _append_log("error", "CONFLICT", endpoint_id)
                return _err("CONFLICT", "A non-deleted endpoint with this name already exists.", field="name", name=name)

    # Apply changes
    changed = False
    now = _now_iso()
    fields = {
        "name": name,
        "template_id": template_id,
        "container_registry_auth_id": container_registry_auth_id,
        "image": image,
        "gpu_type": gpu_type,
        "min_workers": min_workers,
        "max_workers": max_workers,
        "idle_timeout_seconds": idle_timeout_seconds,
        "env": env,
        "auth_mode": auth_mode,
        "request_schema": request_schema,
    }
    for k, v in fields.items():
        if v is not None and v != ep.get(k):
            ep[k] = v
            changed = True

    if not changed:
        _append_log("ok", None, endpoint_id)
        return {"endpoint": dict(ep)}

    # Lifecycle transition: active -> updating when config changed
    status = ep.get("status")
    if status == "active":
        ep["status"] = "updating"
    elif status in ("deploying", "updating", "error"):
        # allow updates; remain updating for deploy/redeploy semantics
        ep["status"] = "updating"
    else:
        _append_log("error", "INVALID_TRANSITION", endpoint_id)
        return _err("INVALID_TRANSITION", "Endpoint cannot be updated from its current status.", endpoint_id=endpoint_id, status=status)

    ep["updated_at"] = now
    endpoints[idx] = ep
    _save("endpoints.json", endpoints)

    _append_log("ok", None, endpoint_id)
    return {"endpoint": dict(ep)}

