def list_templates(kind=None, status=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0442000" if __import__("os").path.isdir("./environment_mix/0442000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    ts = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint_name, status_code, credential_id=None, meta=None):
        for fname in ("request_logs.json", "requests.json", "usage.json", "audit_logs.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                rows = _load(fname)
                latency_ms = int((time.time() - t0) * 1000)
                row = {
                    "id": "req_" + base64.b32encode(os.urandom(10)).decode("utf-8").rstrip("=").lower(),
                    "service": "runpod",
                    "endpoint": endpoint_name,
                    "credential_id": credential_id,
                    "status": status_code,
                    "timestamp": ts,
                    "latency_ms": latency_ms,
                }
                if isinstance(meta, dict) and meta:
                    row["meta"] = meta
                rows.append(row)
                _save(fname, rows)
                break

    # --- Validate inputs ---
    if kind is not None:
        if not isinstance(kind, str):
            _log("list-templates", "VALIDATION_ERROR", meta={"field": "kind"})
            return _err("VALIDATION_ERROR", "kind must be a string", field="kind")
        if kind not in ("pod", "endpoint", "generic"):
            _log("list-templates", "VALIDATION_ERROR", meta={"field": "kind"})
            return _err("VALIDATION_ERROR", "Invalid kind", field="kind", allowed=["pod", "endpoint", "generic"])

    if status is not None:
        if not isinstance(status, str):
            _log("list-templates", "VALIDATION_ERROR", meta={"field": "status"})
            return _err("VALIDATION_ERROR", "status must be a string", field="status")
        if status not in ("active", "archived", "deleted"):
            _log("list-templates", "VALIDATION_ERROR", meta={"field": "status"})
            return _err("VALIDATION_ERROR", "Invalid status", field="status", allowed=["active", "archived", "deleted"])

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        _log("list-templates", "VALIDATION_ERROR", meta={"field": "limit"})
        return _err("VALIDATION_ERROR", "limit must be an integer", field="limit")
    if limit < 1 or limit > 200:
        _log("list-templates", "VALIDATION_ERROR", meta={"field": "limit"})
        return _err("VALIDATION_ERROR", "limit out of range (1..200)", field="limit")

    if sort is None:
        sort = "created_at"
    if not isinstance(sort, str):
        _log("list-templates", "VALIDATION_ERROR", meta={"field": "sort"})
        return _err("VALIDATION_ERROR", "sort must be a string", field="sort")
    if sort not in ("created_at", "updated_at", "name"):
        _log("list-templates", "VALIDATION_ERROR", meta={"field": "sort"})
        return _err("VALIDATION_ERROR", "Invalid sort field", field="sort", allowed=["created_at", "updated_at", "name"])

    if order is None:
        order = "desc"
    if not isinstance(order, str):
        _log("list-templates", "VALIDATION_ERROR", meta={"field": "order"})
        return _err("VALIDATION_ERROR", "order must be a string", field="order")
    if order not in ("asc", "desc"):
        _log("list-templates", "VALIDATION_ERROR", meta={"field": "order"})
        return _err("VALIDATION_ERROR", "Invalid order", field="order", allowed=["asc", "desc"])

    start = 0
    if cursor is not None:
        if not isinstance(cursor, str):
            _log("list-templates", "VALIDATION_ERROR", meta={"field": "cursor"})
            return _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")
        # Opaque cursor: accept base64url-encoded integer offset, or raw integer string.
        parsed = None
        if cursor.strip().isdigit():
            parsed = int(cursor.strip())
        else:
            try:
                pad = "=" * (-len(cursor) % 4)
                decoded = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
                if decoded.isdigit():
                    parsed = int(decoded)
            except Exception:
                parsed = None
        if parsed is None or parsed < 0:
            _log("list-templates", "VALIDATION_ERROR", meta={"field": "cursor"})
            return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
        start = parsed

    # --- Load, filter, sort ---
    templates = _load("templates.json")
    rows = []
    for r in templates:
        if not isinstance(r, dict):
            continue
        if kind is not None and r.get("kind") != kind:
            continue
        if status is not None:
            if r.get("status") != status:
                continue
        # If status filter is not provided, include non-deleted and deleted alike (visible), matching description.
        rows.append(r)

    def _sort_key(v):
        if sort in ("created_at", "updated_at"):
            x = v.get(sort)
            # ISO strings sort lexicographically; None last.
            return (x is None, x or "")
        if sort == "name":
            x = v.get("name")
            return (x is None, (x or "").lower(), x or "")
        return (True, "")

    reverse = (order == "desc")
    rows.sort(key=_sort_key, reverse=reverse)

    total = len(rows)
    page = rows[start:start + limit]
    next_cursor = None
    has_more = start + limit < total
    if has_more:
        nxt = str(start + limit).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(nxt).decode("utf-8").rstrip("=")

    _log("list-templates", "OK", meta={"count": len(page), "total": total, "has_more": has_more})
    return {
        "templates": page,
        "pagination": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more
        }
    }

def get_template(template_id, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0442000" if __import__("os").path.isdir("./environment_mix/0442000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # No request-log/audit/usage collection declared in schema; nothing to record/enforce.

    if not isinstance(template_id, str):
        return _err("VALIDATION_ERROR", "template_id must be a string.", field="template_id")
    if not re.match(r"^tmpl_[0-9A-Z]{26}$", template_id):
        return _err("VALIDATION_ERROR", "template_id does not match required format.", field="template_id", pattern="^tmpl_[0-9A-Z]{26}$")

    templates = _load("templates.json")
    tmpl = None
    for r in templates:
        if isinstance(r, dict) and r.get("id") == template_id:
            tmpl = r
            break

    if tmpl is None:
        return _err("NOT_FOUND", "Template not found.", template_id=template_id)

    # Policy: return full Template record (including status/deleted_at if present).
    return {
        "template": tmpl,
        "meta": {
            "template_id": template_id,
            "latency_ms": int((time.time() - _t0) * 1000),
            "retrieved_at": _now,
        },
    }

def create_template(name, kind, description=None, default_image=None, default_env=None, default_gpu_type=None, default_gpu_count=None, default_disk_gb=None, default_ports=None, status=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0442000" if __import__("os").path.isdir("./environment_mix/0442000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create-template"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _find_log_collection():
        for fn in ("request_logs.json", "usage_logs.json", "requests.json", "audit_logs.json", "usage.json", "events.json", "api_requests.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "request_logs.json"

    def _append_log(status, error_code=None, resource_id=None):
        fn = _find_log_collection()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + os.urandom(12).hex(),
            "timestamp": _now_iso(),
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "resource_id": resource_id,
            "latency_ms": int(max(0, (time.time() - t0) * 1000)),
        })
        _save(fn, logs)

    if not isinstance(name, str) or not name.strip():
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name is required and must be a non-empty string.", field="name")
    if not isinstance(kind, str) or kind not in ("pod", "endpoint", "generic"):
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "kind must be one of: pod, endpoint, generic.", field="kind")
    if description is not None and not isinstance(description, str):
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "description must be a string.", field="description")
    if default_image is not None and (not isinstance(default_image, str) or not default_image.strip()):
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "default_image must be a non-empty string.", field="default_image")
    if default_env is not None and not isinstance(default_env, dict):
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "default_env must be an object.", field="default_env")
    if default_gpu_type is not None and (not isinstance(default_gpu_type, str) or not default_gpu_type.strip()):
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "default_gpu_type must be a non-empty string.", field="default_gpu_type")
    if default_gpu_count is not None:
        if not isinstance(default_gpu_count, int) or isinstance(default_gpu_count, bool) or default_gpu_count < 0 or default_gpu_count > 64:
            _append_log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "default_gpu_count must be an integer between 0 and 64.", field="default_gpu_count")
        if default_gpu_count == 0:
            default_gpu_count = None
    if default_disk_gb is not None:
        if not isinstance(default_disk_gb, (int, float)) or isinstance(default_disk_gb, bool) or default_disk_gb < 0 or default_disk_gb > 10000:
            _append_log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "default_disk_gb must be a number between 0 and 10000.", field="default_disk_gb")
        if default_disk_gb == 0:
            default_disk_gb = None
    if default_ports is not None:
        if not isinstance(default_ports, list):
            _append_log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "default_ports must be an array of integers.", field="default_ports")
        for i, p in enumerate(default_ports):
            if not isinstance(p, int) or isinstance(p, bool) or p < 1 or p > 65535:
                _append_log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Each default_ports value must be an integer between 1 and 65535.", field="default_ports", index=i)
    if status is not None and status not in ("active", "archived", "deleted"):
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of: active, archived, deleted.", field="status")

    templates = _load("templates.json")
    if not isinstance(templates, list):
        templates = []

    # uniqueness(name) where deleted_at is null
    for t in templates:
        if isinstance(t, dict) and t.get("deleted_at") is None and t.get("name") == name:
            _append_log("error", "CONFLICT")
            return _err("CONFLICT", "A non-deleted template with this name already exists.", field="name")

    # Quota best-effort: enforce a conservative cap if a limit file exists; otherwise no cap.
    # (No explicit quota collection in provided schema.)
    active_count = sum(1 for r in templates if isinstance(r, dict) and r.get("deleted_at") is None)
    quota_cap = None
    limits = _load("limits.json")
    if isinstance(limits, dict):
        quota_cap = limits.get("templates_max")
    if isinstance(quota_cap, int) and quota_cap >= 0 and active_count >= quota_cap:
        _append_log("error", "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Template quota exceeded.", limit=quota_cap)

    now = _now_iso()

    def _gen_id():
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        # 26 chars
        raw = os.urandom(16)
        n = int.from_bytes(raw, "big")
        out = ""
        for _ in range(26):
            out = alphabet[n % 36] + out
            n //= 36
        return "tmpl_" + out

    new_id = _gen_id()
    existing_ids = {r.get("id") for r in templates if isinstance(r, dict)}
    while new_id in existing_ids:
        new_id = _gen_id()

    row = {
        "id": new_id,
        "name": name,
        "description": description,
        "kind": kind,
        "default_image": default_image if default_image is not None else "docker.io/library/ubuntu:latest",
        "default_env": default_env,
        "default_gpu_type": default_gpu_type,
        "default_gpu_count": default_gpu_count,
        "default_disk_gb": default_disk_gb,
        "default_ports": default_ports,
        "status": status if status is not None else "active",
        "deleted_at": now if (status == "deleted") else None,
        "created_at": now,
        "updated_at": now,
    }

    templates.append(row)
    _save("templates.json", templates)

    _append_log("success", None, new_id)
    return {"template": dict(row), "meta": {"created_at": now, "latency_ms": int(max(0, (time.time() - t0) * 1000))}}

def update_template(template_id, name=None, description=None, kind=None, default_image=None, default_env=None, default_gpu_type=None, default_gpu_count=None, default_disk_gb=None, default_ports=None, status=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0442000" if __import__("os").path.isdir("./environment_mix/0442000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    usage_file = None
    for candidate in ("request_logs.json", "requests.json", "usage.json", "audit_logs.json"):
        if os.path.exists(os.path.join(_DB, candidate)):
            usage_file = candidate
            break

    def _log(status_code):
        if not usage_file:
            return
        logs = _load(usage_file)
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": "update-template",
                "status": status_code,
                "timestamp": now,
                "latency_ms": int((time.time() - t0) * 1000),
            }
        )
        _save(usage_file, logs)

    # Validate template_id format
    if not isinstance(template_id, str) or not re.match(r"^tmpl_[0-9A-Z]{26}$", template_id):
        _log(400)
        return _err("VALIDATION_ERROR", "template_id must match ^tmpl_[0-9A-Z]{26}$.", field="template_id")

    # Validate supplied fields
    if name is not None and (not isinstance(name, str) or not name.strip()):
        _log(400)
        return _err("VALIDATION_ERROR", "name must be a non-empty string.", field="name")
    if description is not None and not isinstance(description, str):
        _log(400)
        return _err("VALIDATION_ERROR", "description must be a string.", field="description")
    if kind is not None and (not isinstance(kind, str) or kind not in ("pod", "endpoint", "generic")):
        _log(400)
        return _err("VALIDATION_ERROR", "Invalid kind. Must be one of: pod, endpoint, generic.", field="kind")
    if default_image is not None and not isinstance(default_image, str):
        _log(400)
        return _err("VALIDATION_ERROR", "default_image must be a string.", field="default_image")
    if default_env is not None and not isinstance(default_env, dict):
        _log(400)
        return _err("VALIDATION_ERROR", "default_env must be an object (key/value map).", field="default_env")
    if default_gpu_type is not None and not isinstance(default_gpu_type, str):
        _log(400)
        return _err("VALIDATION_ERROR", "default_gpu_type must be a string.", field="default_gpu_type")
    if default_gpu_count is not None:
        if not isinstance(default_gpu_count, int) or default_gpu_count < 0:
            _log(400)
            return _err("VALIDATION_ERROR", "default_gpu_count must be an integer >= 0.", field="default_gpu_count")
        if default_gpu_count > 64:
            _log(400)
            return _err("VALIDATION_ERROR", "default_gpu_count must be <= 64.", field="default_gpu_count")
    if default_disk_gb is not None:
        if not isinstance(default_disk_gb, (int, float)) or default_disk_gb < 0:
            _log(400)
            return _err("VALIDATION_ERROR", "default_disk_gb must be a number >= 0.", field="default_disk_gb")
        if default_disk_gb > 10000:
            _log(400)
            return _err("VALIDATION_ERROR", "default_disk_gb must be <= 10000.", field="default_disk_gb")
    if default_ports is not None:
        if not isinstance(default_ports, list):
            _log(400)
            return _err("VALIDATION_ERROR", "default_ports must be an array of integers.", field="default_ports")
        for i, p in enumerate(default_ports):
            if not isinstance(p, int) or p < 1 or p > 65535:
                _log(400)
                return _err("VALIDATION_ERROR", "Each default_ports entry must be an integer between 1 and 65535.", field=f"default_ports[{i}]")
    if status is not None and (not isinstance(status, str) or status not in ("active", "archived", "deleted")):
        _log(400)
        return _err("VALIDATION_ERROR", "Invalid status. Must be one of: active, archived, deleted.", field="status")

    templates = _load("templates.json")
    if not isinstance(templates, list):
        templates = []

    idx = None
    for i, t in enumerate(templates):
        if isinstance(t, dict) and t.get("id") == template_id:
            idx = i
            break

    if idx is None:
        _log(404)
        return _err("NOT_FOUND", "Template not found.", template_id=template_id)

    rec = templates[idx]
    if rec.get("status") == "deleted" or rec.get("deleted_at") is not None:
        _log(409)
        return _err("CONFLICT", "Template is deleted and cannot be modified.", template_id=template_id)

    # uniqueness(name) where deleted_at is NULL
    if name is not None:
        for t in templates:
            if not isinstance(t, dict):
                continue
            if t.get("id") != template_id and t.get("deleted_at") is None and t.get("name") == name:
                _log(409)
                return _err("CONFLICT", "A non-deleted template with this name already exists.", field="name")

    # Apply updates
    changed = False
    for k, v in (
        ("name", name),
        ("description", description),
        ("kind", kind),
        ("default_image", default_image),
        ("default_env", default_env),
        ("default_gpu_type", default_gpu_type),
        ("default_gpu_count", default_gpu_count),
        ("default_disk_gb", default_disk_gb),
        ("default_ports", default_ports),
        ("status", status),
    ):
        if v is not None:
            if rec.get(k) != v:
                rec[k] = v
                changed = True

    if status is not None:
        if status == "deleted":
            rec["deleted_at"] = rec.get("deleted_at") or now
        else:
            # if re-activating from archived, keep deleted_at None
            rec["deleted_at"] = None

    if not changed and status is None:
        # No fields provided that actually change anything
        _log(400)
        return _err("VALIDATION_ERROR", "No updatable fields were provided.")

    # Lifecycle transitions for template status
    # Allowed: active <-> archived, active/archived -> deleted
    prev_status = templates[idx].get("status")
    new_status = rec.get("status")
    allowed = {
        "active": {"archived", "deleted", "active"},
        "archived": {"active", "deleted", "archived"},
        "deleted": {"deleted"},
    }
    if prev_status in allowed and new_status not in allowed[prev_status]:
        _log(409)
        return _err("INVALID_TRANSITION", f"Cannot transition template status from {prev_status} to {new_status}.")

    rec["updated_at"] = now
    templates[idx] = rec
    _save("templates.json", templates)

    _log(200)
    return {"data": rec}

def delete_template(template_id, force=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0442000" if __import__("os").path.isdir("./environment_mix/0442000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "delete-template"

    # ---- audit/log + quota/rate helpers (best-effort if collection exists) ----
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _pick_identity():
        # Ambient auth: if there's any "accounts/workspaces/api_keys" store, choose any active combination.
        # Otherwise, return anonymous context.
        accounts = _load("accounts.json")
        workspaces = _load("workspaces.json")
        api_keys = _load("api_keys.json")
        # Try: api_key -> workspace -> account, preferring active/non-deleted.
        if isinstance(api_keys, list) and api_keys:
            for k in api_keys:
                if not isinstance(k, dict):
                    continue
                if k.get("deleted_at") is None and k.get("status", "active") in ("active", "enabled"):
                    ws_id = k.get("workspace_id")
                    acct_id = k.get("account_id")
                    ws = None
                    acct = None
                    if ws_id and isinstance(workspaces, list):
                        ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == ws_id and w.get("deleted_at") is None), None)
                    if acct_id and isinstance(accounts, list):
                        acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == acct_id and a.get("deleted_at") is None), None)
                    return {
                        "credential_type": "api_key",
                        "credential_id": k.get("id"),
                        "credential": k.get("key") or k.get("id"),
                        "workspace_id": (ws or {}).get("id") if ws else ws_id,
                        "account_id": (acct or {}).get("id") if acct else acct_id,
                    }
        # Fallback: first workspace/account if present.
        if isinstance(workspaces, list) and workspaces:
            ws = next((w for w in workspaces if isinstance(w, dict) and w.get("deleted_at") is None), None)
            if ws:
                return {"credential_type": "ambient", "credential_id": None, "credential": None, "workspace_id": ws.get("id"), "account_id": ws.get("account_id")}
        if isinstance(accounts, list) and accounts:
            acct = next((a for a in accounts if isinstance(a, dict) and a.get("deleted_at") is None), None)
            if acct:
                return {"credential_type": "ambient", "credential_id": None, "credential": None, "workspace_id": None, "account_id": acct.get("id")}
        return {"credential_type": "ambient", "credential_id": None, "credential": None, "workspace_id": None, "account_id": None}

    def _enforce_limits(identity):
        # If request_logs/usage exists, enforce a simple per-minute rate limit if declared.
        # Schema not provided; implement generic behavior:
        # - request_logs.json: append all calls
        # - rate limiting by counting last 60s per credential_id (or ambient bucket)
        logs = _load("request_logs.json")
        rate_limits = _load("rate_limits.json")
        quotas = _load("quotas.json")

        # Defaults if nothing declared
        per_minute = None
        per_day = None

        # Parse possible policies
        cred_key = identity.get("credential_id") or identity.get("credential") or "ambient"
        if isinstance(rate_limits, list):
            # choose most specific matching rule
            for r in rate_limits:
                if not isinstance(r, dict):
                    continue
                if r.get("deleted_at") is None and r.get("status", "active") in ("active", "enabled"):
                    if r.get("credential_id") == identity.get("credential_id") or r.get("credential") == identity.get("credential"):
                        if isinstance(r.get("per_minute"), int):
                            per_minute = r["per_minute"]
                        if isinstance(r.get("per_day"), int):
                            per_day = r["per_day"]
                        break
        if per_minute is None:
            per_minute = 120  # safe default for local service dynamics
        if per_day is None:
            per_day = 20000

        if not isinstance(logs, list):
            return None, logs, None  # can't enforce; still will log if list later

        now = datetime.datetime.utcnow()
        # Rate: last 60 seconds
        recent = 0
        day = 0
        for row in logs:
            if not isinstance(row, dict):
                continue
            if (row.get("credential_id") or row.get("credential") or "ambient") != cred_key:
                continue
            ts = row.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                # accept Z or naive iso
                s = ts[:-1] if ts.endswith("Z") else ts
                dt = datetime.datetime.fromisoformat(s)
            except Exception:
                continue
            delta = (now - dt).total_seconds()
            if 0 <= delta <= 60:
                recent += 1
            if 0 <= delta <= 86400:
                day += 1

        if per_minute is not None and recent >= per_minute:
            return _err("RATE_LIMIT", "Rate limit exceeded"), logs, cred_key
        if per_day is not None and day >= per_day:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded"), logs, cred_key
        return None, logs, cred_key

    def _log(logs, identity, cred_key, status_code, error_code=None):
        if not isinstance(logs, list):
            return
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
            "timestamp": _now(),
            "endpoint": endpoint,
            "credential_type": identity.get("credential_type"),
            "credential_id": identity.get("credential_id"),
            "credential": identity.get("credential"),
            "account_id": identity.get("account_id"),
            "workspace_id": identity.get("workspace_id"),
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    identity = _pick_identity()
    limit_err, logs, cred_key = _enforce_limits(identity)
    if limit_err:
        _log(logs, identity, cred_key, status_code=429, error_code=limit_err["error"]["code"])
        return limit_err

    # ---- validate inputs ----
    if not isinstance(template_id, str):
        _log(logs, identity, cred_key, status_code=400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "template_id must be a string")
    if not re.match(r"^tmpl_[0-9A-Z]{26}$", template_id):
        _log(logs, identity, cred_key, status_code=400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "template_id is invalid")
    if force is None:
        force = False
    if not isinstance(force, bool):
        _log(logs, identity, cred_key, status_code=400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "force must be a boolean")

    templates = _load("templates.json")
    if not isinstance(templates, list):
        _log(logs, identity, cred_key, status_code=500, error_code="CONFLICT")
        return _err("CONFLICT", "Datastore error: templates collection is not a list")

    tmpl_idx = None
    tmpl = None
    for i, row in enumerate(templates):
        if isinstance(row, dict) and row.get("id") == template_id:
            tmpl_idx = i
            tmpl = row
            break
    if tmpl is None:
        _log(logs, identity, cred_key, status_code=404, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Template not found", template_id=template_id)

    # UNAUTHORIZED if you do not own the Template:
    # With no ownership fields in schema, enforce only if template has account_id/workspace_id and it mismatches ambient identity.
    for owner_field in ("account_id", "workspace_id"):
        if owner_field in tmpl and tmpl.get(owner_field) is not None:
            if identity.get(owner_field) is None or identity.get(owner_field) != tmpl.get(owner_field):
                _log(logs, identity, cred_key, status_code=401, error_code="UNAUTHORIZED")
                return _err("UNAUTHORIZED", "Not authorized to delete this template")

    if tmpl.get("deleted_at") is not None or tmpl.get("status") == "deleted":
        _log(logs, identity, cred_key, status_code=409, error_code="CONFLICT")
        return _err("CONFLICT", "Template is already deleted", template_id=template_id)

    # If force is false, enforce referential integrity against non-deleted pods/endpoints.
    pods = _load("pods.json")
    endpoints = _load("endpoints.json")
    referenced_by = {"pods": [], "endpoints": []}

    if isinstance(pods, list):
        for p in pods:
            if not isinstance(p, dict):
                continue
            if p.get("deleted_at") is None and p.get("template_id") == template_id and p.get("status") != "deleted":
                referenced_by["pods"].append(p.get("id"))
    if isinstance(endpoints, list):
        for e in endpoints:
            if not isinstance(e, dict):
                continue
            if e.get("deleted_at") is None and e.get("template_id") == template_id and e.get("status") != "deleted":
                referenced_by["endpoints"].append(e.get("id"))

    if (referenced_by["pods"] or referenced_by["endpoints"]) and not force:
        _log(logs, identity, cred_key, status_code=409, error_code="CONFLICT")
        return _err(
            "CONFLICT",
            "Template is still referenced; set force=true to delete anyway",
            referenced_by=referenced_by,
        )

    # Business rule: soft delete only; existing pods/endpoints remain valid with historical template_id.
    # Lifecycle transitions: active/archived -> deleted
    current = tmpl.get("status")
    allowed = {"active": {"archived", "deleted"}, "archived": {"active", "deleted"}, "deleted": set()}
    if current not in allowed:
        _log(logs, identity, cred_key, status_code=400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Template has invalid status value", status=current)
    if "deleted" not in allowed.get(current, set()):
        _log(logs, identity, cred_key, status_code=409, error_code="INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", f"Cannot transition template from {current} to deleted")

    now = _now()
    new_row = dict(tmpl)
    new_row["status"] = "deleted"
    new_row["deleted_at"] = now
    new_row["updated_at"] = now
    templates[tmpl_idx] = new_row
    _save("templates.json", templates)

    _log(logs, identity, cred_key, status_code=200, error_code=None)
    return {"template": new_row}

def list_network_volumes(region=None, status=None, name=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0442000" if __import__("os").path.isdir("./environment_mix/0442000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list-network-volumes"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _pick_identity():
        accounts = _load("accounts.json")
        workspaces = _load("workspaces.json")
        api_keys = _load("api_keys.json")
        if isinstance(api_keys, list) and api_keys:
            for k in api_keys:
                if not isinstance(k, dict):
                    continue
                if k.get("deleted_at") is None and k.get("status", "active") in ("active", "enabled"):
                    ws_id = k.get("workspace_id")
                    acct_id = k.get("account_id")
                    ws = None
                    acct = None
                    if ws_id and isinstance(workspaces, list):
                        ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == ws_id and w.get("deleted_at") is None), None)
                    if acct_id and isinstance(accounts, list):
                        acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == acct_id and a.get("deleted_at") is None), None)
                    return {
                        "credential_type": "api_key",
                        "credential_id": k.get("id"),
                        "credential": k.get("key") or k.get("id"),
                        "workspace_id": (ws or {}).get("id") if ws else ws_id,
                        "account_id": (acct or {}).get("id") if acct else acct_id,
                    }
        if isinstance(workspaces, list) and workspaces:
            ws = next((w for w in workspaces if isinstance(w, dict) and w.get("deleted_at") is None), None)
            if ws:
                return {"credential_type": "ambient", "credential_id": None, "credential": None, "workspace_id": ws.get("id"), "account_id": ws.get("account_id")}
        if isinstance(accounts, list) and accounts:
            acct = next((a for a in accounts if isinstance(a, dict) and a.get("deleted_at") is None), None)
            if acct:
                return {"credential_type": "ambient", "credential_id": None, "credential": None, "workspace_id": None, "account_id": acct.get("id")}
        return {"credential_type": "ambient", "credential_id": None, "credential": None, "workspace_id": None, "account_id": None}

    def _enforce_limits(identity):
        logs = _load("request_logs.json")
        rate_limits = _load("rate_limits.json")
        quotas = _load("quotas.json")

        per_minute = None
        per_day = None
        cred_key = identity.get("credential_id") or identity.get("credential") or "ambient"

        if isinstance(rate_limits, list):
            for r in rate_limits:
                if not isinstance(r, dict):
                    continue
                if r.get("deleted_at") is None and r.get("status", "active") in ("active", "enabled"):
                    if r.get("credential_id") == identity.get("credential_id") or r.get("credential") == identity.get("credential"):
                        if isinstance(r.get("per_minute"), int):
                            per_minute = r["per_minute"]
                        if isinstance(r.get("per_day"), int):
                            per_day = r["per_day"]
                        break

        if per_minute is None:
            per_minute = 120
        if per_day is None:
            per_day = 20000

        if not isinstance(logs, list):
            return None, logs, cred_key

        now = datetime.datetime.utcnow()
        recent = 0
        day = 0
        for row in logs:
            if not isinstance(row, dict):
                continue
            if (row.get("credential_id") or row.get("credential") or "ambient") != cred_key:
                continue
            ts = row.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                s = ts[:-1] if ts.endswith("Z") else ts
                dt = datetime.datetime.fromisoformat(s)
            except Exception:
                continue
            delta = (now - dt).total_seconds()
            if 0 <= delta <= 60:
                recent += 1
            if 0 <= delta <= 86400:
                day += 1

        if per_minute is not None and recent >= per_minute:
            return _err("RATE_LIMIT", "Rate limit exceeded"), logs, cred_key
        if per_day is not None and day >= per_day:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded"), logs, cred_key
        return None, logs, cred_key

    def _log(logs, identity, status_code, error_code=None):
        if not isinstance(logs, list):
            return
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
            "timestamp": _now(),
            "endpoint": endpoint,
            "credential_type": identity.get("credential_type"),
            "credential_id": identity.get("credential_id"),
            "credential": identity.get("credential"),
            "account_id": identity.get("account_id"),
            "workspace_id": identity.get("workspace_id"),
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)

    identity = _pick_identity()
    limit_err, logs, _cred_key = _enforce_limits(identity)
    if limit_err:
        _log(logs, identity, status_code=429, error_code=limit_err["error"]["code"])
        return limit_err

    # ---- validate inputs ----
    if region is not None and not isinstance(region, str):
        _log(logs, identity, status_code=400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "region must be a string")
    if name is not None and not isinstance(name, str):
        _log(logs, identity, status_code=400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name must be a string")
    valid_status = {"available", "in_use", "updating", "error", "deleted"}
    if status is not None:
        if not isinstance(status, str) or status not in valid_status:
            _log(logs, identity, status_code=400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status is invalid", allowed=sorted(valid_status))
    if limit is None:
        limit = 20
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log(logs, identity, status_code=400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100")
    valid_sort_by = {"created_at", "updated_at", "name", "size_gb", "status"}
    if sort_by is None:
        sort_by = "created_at"
    if not isinstance(sort_by, str) or sort_by not in valid_sort_by:
        _log(logs, identity, status_code=400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort_by is invalid", allowed=sorted(valid_sort_by))
    if sort_order is None:
        sort_order = "desc"
    if not isinstance(sort_order, str) or sort_order not in ("asc", "desc"):
        _log(logs, identity, status_code=400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort_order is invalid", allowed=["asc", "desc"])
    if cursor is not None and not isinstance(cursor, str):
        _log(logs, identity, status_code=400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a string")

    # Cursor format: base64url(JSON({"offset":int}))
    offset = 0
    if cursor:
        try:
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict) or not isinstance(obj.get("offset"), int) or obj["offset"] < 0:
                _log(logs, identity, status_code=400, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "cursor is invalid")
            offset = obj["offset"]
        except (ValueError, json.JSONDecodeError):
            _log(logs, identity, status_code=400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid")

    vols = _load("network_volumes.json")
    if not isinstance(vols, list):
        _log(logs, identity, status_code=500, error_code="CONFLICT")
        return _err("CONFLICT", "Datastore error: network_volumes collection is not a list")

    # Filter
    out = []
    for v in vols:
        if not isinstance(v, dict):
            continue
        if region is not None and v.get("region") != region:
            continue
        if status is not None and v.get("status") != status:
            continue
        if name is not None and v.get("name") != name:
            continue
        out.append(v)

    # Sort
    def _sort_key(v):
        val = v.get(sort_by)
        # normalize datetimes to sortable strings; missing last
        if sort_by in ("created_at", "updated_at"):
            if isinstance(val, str):
                return (0, val)
            return (1, "")
        if sort_by == "size_gb":
            if isinstance(val, (int, float)):
                return (0, float(val))
            return (1, 0.0)
        if sort_by in ("name", "status"):
            if isinstance(val, str):
                return (0, val.lower())
            return (1, "")
        return (0, val)

    reverse = (sort_order == "desc")
    out.sort(key=_sort_key, reverse=reverse)

    total = len(out)
    page = out[offset: offset + limit]
    next_cursor = None
    has_more = offset + limit < total
    if has_more:
        payload = json.dumps({"offset": offset + limit}, separators=(",", ":"))
        next_cursor = base64.urlsafe_b64encode(payload.encode("utf-8")).decode("utf-8").rstrip("=")

    resp = {
        "network_volumes": page,
        "page": {
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "total": total,
            "sort_by": sort_by,
            "sort_order": sort_order,
        },
    }

    _log(logs, identity, status_code=200, error_code=None)
    return resp

def get_network_volume(volume_id, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0442000" if __import__("os").path.isdir("./environment_mix/0442000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint_name = "get-network-volume"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _find_log_collection():
        for fn in ("request_logs.json", "usage_logs.json", "requests.json", "audit_logs.json", "usage.json", "events.json", "api_requests.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "request_logs.json"

    def _append_log(status, error_code=None, resource_id=None):
        fn = _find_log_collection()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "req_" + os.urandom(12).hex(),
                "timestamp": _now_iso(),
                "endpoint": endpoint_name,
                "status": status,
                "error_code": error_code,
                "resource_id": resource_id,
                "latency_ms": int(max(0, (time.time() - t0) * 1000)),
            }
        )
        _save(fn, logs)

    if not isinstance(volume_id, str) or not volume_id.strip():
        _append_log("error", "VALIDATION_ERROR", None)
        return _err("VALIDATION_ERROR", "volume_id must be a non-empty string.", field="volume_id")

    vols = _load("network_volumes.json")
    if not isinstance(vols, list):
        vols = []

    vol = next((v for v in vols if isinstance(v, dict) and v.get("id") == volume_id), None)
    if vol is None:
        vol = next(
            (v for v in vols if isinstance(v, dict) and isinstance(v.get("id"), str) and v.get("id").lower() == volume_id.lower()),
            None,
        )

    if vol is None:
        _append_log("error", "NOT_FOUND", volume_id)
        return _err("NOT_FOUND", "Network volume not found.", volume_id=volume_id)

    _append_log("ok", None, volume_id)
    return {"volume": dict(vol)}

def create_network_volume(name, region, size_gb, filesystem, **_extra):
    import json, os, datetime, time, re, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0442000" if __import__("os").path.isdir("./environment_mix/0442000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    # --- observable service dynamics: request log + quota/rate limiting ---
    logs = _load("request_logs.json")

    # rate limit: 60 creates / 5 minutes across store
    window_s = 300
    limit = 60
    cutoff = time.time() - window_s
    recent = 0
    for r in logs:
        ts = r.get("ts_unix")
        if isinstance(ts, (int, float)) and ts >= cutoff and r.get("endpoint") == "create-network-volume":
            recent += 1
    if recent >= limit:
        logs.append({
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": "create-network-volume",
            "status": "RATE_LIMIT",
            "ts": now,
            "ts_unix": time.time(),
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # --- ambient auth ---
    # No credential param; assume authenticated if service is usable. If datastore is missing entirely, treat as unauthorized.
    # But _load returns [] if missing; we can still create. So UNAUTHORIZED only if we cannot persist.
    if not os.path.isdir(_DB):
        logs.append({
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": "create-network-volume",
            "status": "UNAUTHORIZED",
            "ts": now,
            "ts_unix": time.time(),
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)
        return _err("UNAUTHORIZED", "Not authenticated")

    # --- validate inputs ---
    if not isinstance(name, str) or not name.strip():
        logs.append({
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": "create-network-volume",
            "status": "VALIDATION_ERROR",
            "ts": now,
            "ts_unix": time.time(),
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "name is required", field="name")

    if not isinstance(region, str) or not region.strip():
        logs.append({
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": "create-network-volume",
            "status": "VALIDATION_ERROR",
            "ts": now,
            "ts_unix": time.time(),
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "region is required", field="region")

    if not isinstance(size_gb, (int, float)) or isinstance(size_gb, bool):
        logs.append({
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": "create-network-volume",
            "status": "VALIDATION_ERROR",
            "ts": now,
            "ts_unix": time.time(),
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "size_gb must be a number", field="size_gb")

    if size_gb < 1 or size_gb > 65536:
        logs.append({
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": "create-network-volume",
            "status": "VALIDATION_ERROR",
            "ts": now,
            "ts_unix": time.time(),
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "size_gb out of range (1..65536)", field="size_gb", min=1, max=65536)

    if filesystem not in ("ext4", "xfs"):
        logs.append({
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": "create-network-volume",
            "status": "VALIDATION_ERROR",
            "ts": now,
            "ts_unix": time.time(),
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "filesystem must be one of: ext4, xfs", field="filesystem", allowed=["ext4", "xfs"])

    vols = _load("network_volumes.json")
    if not isinstance(vols, list):
        vols = []

    # uniqueness: unique(name) where deleted_at is NULL
    for v in vols:
        if not isinstance(v, dict):
            continue
        if v.get("deleted_at") is None and v.get("name") == name:
            logs.append({
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": "create-network-volume",
                "status": "CONFLICT",
                "ts": now,
                "ts_unix": time.time(),
                "latency_ms": int((time.time() - t0) * 1000),
            })
            _save("request_logs.json", logs)
            return _err("CONFLICT", "A non-deleted network volume with this name already exists", field="name", name=name)

    # quota: max 20 non-deleted volumes
    active_count = 0
    for v in vols:
        if isinstance(v, dict) and v.get("deleted_at") is None:
            active_count += 1
    if active_count >= 20:
        logs.append({
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": "create-network-volume",
            "status": "QUOTA_EXCEEDED",
            "ts": now,
            "ts_unix": time.time(),
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)
        return _err("QUOTA_EXCEEDED", "Network volume quota exceeded", limit=20)

    # conflict: region cannot be accessed (no region catalog in schema; infer from existing pods/volumes)
    # If there are existing resources, require region to be one of those seen; if no resources exist, allow any.
    pods = _load("pods.json")
    seen_regions = set()
    if isinstance(pods, list):
        for p in pods:
            if isinstance(p, dict) and p.get("provider_region"):
                seen_regions.add(p.get("provider_region"))
    for v in vols:
        if isinstance(v, dict) and v.get("region"):
            seen_regions.add(v.get("region"))
    if seen_regions and region not in seen_regions:
        logs.append({
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": "create-network-volume",
            "status": "CONFLICT",
            "ts": now,
            "ts_unix": time.time(),
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)
        return _err("CONFLICT", "Requested region cannot be accessed", field="region", region=region)

    # id generator: vol_ + 26 base32 chars (0-9A-Z)
    alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    existing_ids = {v.get("id") for v in vols if isinstance(v, dict)}
    def _new_id():
        while True:
            s = "".join(random.choice(alphabet) for _ in range(26))
            vid = "vol_" + s
            if vid not in existing_ids:
                return vid

    vol = {
        "id": _new_id(),
        "name": name,
        "region": region,
        "size_gb": float(size_gb) if isinstance(size_gb, float) else (int(size_gb) if isinstance(size_gb, int) else float(size_gb)),
        "filesystem": filesystem,
        "mounts": [],
        "status": "available",
        "deleted_at": None,
        "created_at": now,
        "updated_at": now,
    }

    vols.append(vol)

    # persist
    try:
        _save("network_volumes.json", vols)
    except Exception as e:
        logs.append({
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": "create-network-volume",
            "status": "UNAUTHORIZED",
            "ts": now,
            "ts_unix": time.time(),
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)
        return _err("UNAUTHORIZED", "Not authenticated or unable to persist changes", detail=str(e))

    logs.append({
        "id": f"req_{int(time.time()*1000)}",
        "endpoint": "create-network-volume",
        "status": "OK",
        "ts": now,
        "ts_unix": time.time(),
        "latency_ms": int((time.time() - t0) * 1000),
    })
    _save("request_logs.json", logs)

    return {"volume": vol}

