            }
        )
        _save(fn, logs)

    def _as_number(x):
        if isinstance(x, (int, float)) and not isinstance(x, bool):
            return float(x)
        return None

    if not isinstance(volume_id, str) or not volume_id.strip():
        _append_log("error", "VALIDATION_ERROR", None)
        return _err("VALIDATION_ERROR", "volume_id must be a non-empty string.", field="volume_id")

    if name is not None and (not isinstance(name, str) or not name.strip()):
        _append_log("error", "VALIDATION_ERROR", volume_id)
        return _err("VALIDATION_ERROR", "name must be a non-empty string.", field="name")

    if filesystem is not None and filesystem not in ("ext4", "xfs"):
        _append_log("error", "VALIDATION_ERROR", volume_id)
        return _err("VALIDATION_ERROR", "filesystem must be one of 'ext4' or 'xfs'.", field="filesystem", allowed=["ext4", "xfs"])

    if size_gb is not None:
        s = _as_number(size_gb)
        if s is None:
            _append_log("error", "VALIDATION_ERROR", volume_id)
            return _err("VALIDATION_ERROR", "size_gb must be a number.", field="size_gb")
        if s < 1 or s > 65536:
            _append_log("error", "VALIDATION_ERROR", volume_id)
            return _err("VALIDATION_ERROR", "size_gb must be between 1 and 65536.", field="size_gb")
        size_gb = s

    vols = _load("network_volumes.json")
    if not isinstance(vols, list):
        vols = []

    idx = next((i for i, v in enumerate(vols) if isinstance(v, dict) and v.get("id") == volume_id), None)
    if idx is None:
        idx = next((i for i, v in enumerate(vols) if isinstance(v, dict) and isinstance(v.get("id"), str) and v.get("id").lower() == volume_id.lower()), None)
    if idx is None:
        _append_log("error", "NOT_FOUND", volume_id)
        return _err("NOT_FOUND", "Network volume not found.", volume_id=volume_id)

    vol = vols[idx]
    if vol.get("deleted_at") is not None or vol.get("status") == "deleted":
        _append_log("error", "CONFLICT", volume_id)
        return _err("CONFLICT", "Network volume is deleted and cannot be updated.", volume_id=volume_id, status=vol.get("status"))

    # unique(name) where not deleted
    if name is not None:
        for other in vols:
            if not isinstance(other, dict):
                continue
            if other.get("id") == vol.get("id"):
                continue
            if other.get("deleted_at") is None and isinstance(other.get("name"), str) and other.get("name") == name:
                _append_log("error", "CONFLICT", volume_id)
                return _err("CONFLICT", "A non-deleted volume with this name already exists.", field="name", name=name)

    # Only allow size increases, never decrease
    if size_gb is not None:
        cur = _as_number(vol.get("size_gb"))
        if cur is not None and size_gb < cur:
            _append_log("error", "INVALID_TRANSITION", volume_id)
            return _err("INVALID_TRANSITION", "size_gb can only be increased (never decreased).", field="size_gb", current=cur, requested=size_gb)

    changed = False
    now = _now_iso()

    if name is not None and name != vol.get("name"):
        vol["name"] = name
        changed = True
    if filesystem is not None and filesystem != vol.get("filesystem"):
        vol["filesystem"] = filesystem
        changed = True
    if size_gb is not None and size_gb != vol.get("size_gb"):
        vol["size_gb"] = size_gb
        changed = True

    if not changed:
        _append_log("ok", None, volume_id)
        return {"volume": dict(vol)}

    # Transition through updating
    st = vol.get("status")
    allowed_from = ("available", "in_use", "updating", "error")
    if st not in allowed_from:
        _append_log("error", "INVALID_TRANSITION", volume_id)
        return _err("INVALID_TRANSITION", "Network volume cannot be updated from its current status.", volume_id=volume_id, status=st)

    vol["status"] = "updating"
    vol["updated_at"] = now
    vols[idx] = vol
    _save("network_volumes.json", vols)

    _append_log("ok", None, volume_id)
    return {"volume": dict(vol)}

def delete_network_volume(volume_id, force=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0442000" if __import__("os").path.isdir("./environment_mix/0442000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint_name = "delete-network-volume"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _find_log_collection():
        for fn in ("usage_logs.json", "request_logs.json", "api_requests.json", "requests.json", "audit_logs.json", "events.json", "usage.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "usage_logs.json"

    def _append_log(status, error_code=None, resource_id=None):
        fn = _find_log_collection()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "req_" + os.urandom(12).hex(),
                "timestamp": _now_iso(),
                "endpoint": endpoint_name,
                "status": status,
                "error_code": error_code,
                "resource_id": resource_id,
                "latency_ms": int(max(0, (time.time() - t0) * 1000)),
            }
        )
        _save(fn, logs)

    if not isinstance(volume_id, str) or not volume_id.strip():
        _append_log("error", "VALIDATION_ERROR", None)
        return _err("VALIDATION_ERROR", "volume_id must be a non-empty string.", field="volume_id")
    if force is not None and not isinstance(force, bool):
        _append_log("error", "VALIDATION_ERROR", volume_id)
        return _err("VALIDATION_ERROR", "force must be a boolean.", field="force")
    force = bool(force) if force is not None else False

    vols = _load("network_volumes.json")
    if not isinstance(vols, list):
        vols = []

    idx = next((i for i, v in enumerate(vols) if isinstance(v, dict) and v.get("id") == volume_id), None)
    if idx is None:
        idx = next((i for i, v in enumerate(vols) if isinstance(v, dict) and isinstance(v.get("id"), str) and v.get("id").lower() == volume_id.lower()), None)
    if idx is None:
        _append_log("error", "NOT_FOUND", volume_id)
        return _err("NOT_FOUND", "Network volume not found.", volume_id=volume_id)

    vol = vols[idx]
    if vol.get("status") == "deleted" or vol.get("deleted_at") is not None:
        _append_log("error", "INVALID_TRANSITION", volume_id)
        return _err("INVALID_TRANSITION", "Network volume is already deleted.", volume_id=volume_id)

    mounts = vol.get("mounts")
    if not isinstance(mounts, list):
        mounts = []

    # Business rule: cannot delete while in_use unless mounts array empty; force can override in-use check,
    # but if mounts still exist, it's still "in use" in a meaningful way unless force true.
    if mounts and not force:
        _append_log("error", "CONFLICT", volume_id)
        return _err("CONFLICT", "Volume has active mounts and cannot be deleted unless force=true.", volume_id=volume_id, mounts=mounts)

    if vol.get("status") == "in_use" and mounts and not force:
        _append_log("error", "CONFLICT", volume_id)
        return _err("CONFLICT", "Volume is in use and cannot be deleted.", volume_id=volume_id, status=vol.get("status"))

    # If status is in_use but mounts empty, allow deletion (per business rule)
    if vol.get("status") == "in_use" and not mounts:
        # ok to proceed
        pass

    now = _now_iso()
    vol["status"] = "deleted"
    vol["deleted_at"] = now
    vol["updated_at"] = now
    # On force delete, clear mounts to reflect detachment
    if force and mounts:
        vol["mounts"] = []

    vols[idx] = vol
    _save("network_volumes.json", vols)

    _append_log("ok", None, volume_id)
    return {"volume": dict(vol)}

def list_container_registry_auths(registry=None, status=None, credential_type=None, name=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0442000" if __import__("os").path.isdir("./environment_mix/0442000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _parse_dt(s):
        if not s or not isinstance(s, str): return None
        try:
            if s.endswith("Z"): s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None
    def _log(endpoint, status_s, credential_id=None, meta=None, started_at=None):
        logs = _load("request_logs.json")
        if started_at is None:
            started_at = time.time()
        row = {
            "id": "req_" + os.urandom(12).hex(),
            "timestamp": _now(),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_s,
            "latency_ms": int(max(0, (time.time() - started_at) * 1000)),
            "meta": meta or {}
        }
        logs.append(row)
        _save("request_logs.json", logs)

    started = time.time()
    endpoint_name = "list-container-registry-auths"

    try:
        if registry is not None and not isinstance(registry, str):
            _log(endpoint_name, "error", meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "registry must be a string", field="registry")
        if name is not None and not isinstance(name, str):
            _log(endpoint_name, "error", meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "name must be a string", field="name")
        if status is not None:
            if not isinstance(status, str) or status not in ("active", "revoked", "deleted"):
                _log(endpoint_name, "error", meta={"code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "status must be one of: active, revoked, deleted", field="status")
        if credential_type is not None:
            if not isinstance(credential_type, str) or credential_type not in ("password", "token", "json_key"):
                _log(endpoint_name, "error", meta={"code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "credential_type must be one of: password, token, json_key", field="credential_type")
        if limit is None:
            limit = 20
        if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1 or limit > 100:
            _log(endpoint_name, "error", meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100", field="limit")
        if sort_by is None:
            sort_by = "created_at"
        if sort_order is None:
            sort_order = "desc"
        if sort_by not in ("created_at", "updated_at", "name", "registry", "status"):
            _log(endpoint_name, "error", meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "sort_by not allowed", field="sort_by")
        if sort_order not in ("asc", "desc"):
            _log(endpoint_name, "error", meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "sort_order must be asc or desc", field="sort_order")

        start_index = 0
        if cursor is not None:
            if not isinstance(cursor, str) or cursor.strip() == "":
                _log(endpoint_name, "error", meta={"code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
            try:
                raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
                payload = json.loads(raw.decode("utf-8"))
                if not isinstance(payload, dict) or payload.get("v") != 1 or not isinstance(payload.get("i"), int) or payload["i"] < 0:
                    _log(endpoint_name, "error", meta={"code": "VALIDATION_ERROR"})
                    return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
                start_index = payload["i"]
            except Exception:
                _log(endpoint_name, "error", meta={"code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")

        rows = _load("container_registry_auths.json")
        if not isinstance(rows, list):
            rows = []

        # Filters
        def _match(r):
            if not isinstance(r, dict): 
                return False
            if registry is not None and r.get("registry") != registry:
                return False
            if status is not None and r.get("status") != status:
                return False
            if credential_type is not None and r.get("credential_type") != credential_type:
                return False
            if name is not None and r.get("name") != name:
                return False
            return True

        filtered = [r for r in rows if _match(r)]

        # Sort
        def _key(r):
            v = r.get(sort_by)
            if sort_by in ("created_at", "updated_at"):
                dt = _parse_dt(v)
                return dt or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
            if isinstance(v, str):
                return v.lower()
            return "" if v is None else v

        reverse = (sort_order == "desc")
        try:
            filtered.sort(key=_key, reverse=reverse)
        except Exception:
            # if datastore has mixed types
            filtered.sort(key=lambda r: str(r.get(sort_by, "")), reverse=reverse)

        total = len(filtered)
        if start_index > total:
            _log(endpoint_name, "error", meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "cursor is out of range", field="cursor")

        page = filtered[start_index:start_index + limit]
        next_index = start_index + len(page)
        has_more = next_index < total
        next_cursor = None
        if has_more:
            payload = {"v": 1, "i": next_index}
            b = json.dumps(payload, separators=(",", ":")).encode("utf-8")
            next_cursor = base64.urlsafe_b64encode(b).decode("utf-8").rstrip("=")

        # Strip secret_ciphertext from output
        def _public(r):
            if not isinstance(r, dict): 
                return r
            return {
                "id": r.get("id"),
                "name": r.get("name"),
                "registry": r.get("registry"),
                "username": r.get("username"),
                "credential_type": r.get("credential_type"),
                "secret_last4": r.get("secret_last4"),
                "status": r.get("status"),
                "last_validated_at": r.get("last_validated_at"),
                "deleted_at": r.get("deleted_at"),
                "created_at": r.get("created_at"),
                "updated_at": r.get("updated_at"),
            }

        out = [_public(r) for r in page]
        _log(endpoint_name, "ok", meta={"returned": len(out), "total": total}, started_at=started)
        return {"container_registry_auths": out, "total": total, "has_more": has_more, "next_cursor": next_cursor}
    except Exception as e:
        _log(endpoint_name, "error", meta={"code": "VALIDATION_ERROR", "detail": str(e)}, started_at=started)
        return _err("VALIDATION_ERROR", "Request could not be processed")

