def create_container_registry_auth(name, registry, credential_type, secret, username=None, **_extra):
    import json, os, datetime, time, re, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0442000" if __import__("os").path.isdir("./environment_mix/0442000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create-container-registry-auth"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _find_log_collection():
        for fn in ("request_logs.json", "usage_logs.json", "requests.json", "audit_logs.json", "usage.json", "events.json", "api_requests.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "request_logs.json"

    def _append_log(status, error_code=None, resource_id=None):
        fn = _find_log_collection()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + os.urandom(12).hex(),
            "timestamp": _now_iso(),
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "resource_id": resource_id,
            "latency_ms": int(max(0, (time.time() - t0) * 1000)),
        })
        _save(fn, logs)

    if not isinstance(name, str) or not name.strip():
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name is required and must be a non-empty string.", field="name")
    if not isinstance(registry, str) or not registry.strip():
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "registry is required and must be a non-empty string.", field="registry")
    if not isinstance(credential_type, str) or credential_type not in ("password", "token", "json_key"):
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "credential_type must be one of: password, token, json_key.", field="credential_type")
    if not isinstance(secret, str) or not secret:
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "secret is required and must be a non-empty string.", field="secret")
    if username is not None and (not isinstance(username, str) or not username.strip()):
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "username must be a non-empty string when provided.", field="username")

    # Normalize registry: allow scheme/path, store host portion
    reg = registry.strip()
    reg = re.sub(r"^[a-zA-Z][a-zA-Z0-9+\-.]*://", "", reg)
    reg = reg.split("/")[0].strip()
    if not reg:
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "registry must contain a hostname.", field="registry")

    cras = _load("container_registry_auths.json")
    if not isinstance(cras, list):
        cras = []

    # uniqueness(name) where deleted_at is null
    for c in cras:
        if isinstance(c, dict) and c.get("deleted_at") is None and c.get("name") == name:
            _append_log("error", "CONFLICT")
            return _err("CONFLICT", "A non-deleted container registry auth with this name already exists.", field="name")

    # uniqueness(registry, username) where deleted_at is null
    for c in cras:
        if not isinstance(c, dict) or c.get("deleted_at") is not None:
            continue
        if c.get("registry") == reg and (c.get("username") or None) == (username or None):
            _append_log("error", "CONFLICT")
            return _err("CONFLICT", "A non-deleted container registry auth for this registry/username already exists.", field="registry")

    def _gen_id():
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        raw = os.urandom(16)
        n = int.from_bytes(raw, "big")
        out = ""
        for _ in range(26):
            out = alphabet[n % 36] + out
            n //= 36
        return "cra_" + out

    new_id = _gen_id()
    existing_ids = {r.get("id") for r in cras if isinstance(r, dict)}
    while new_id in existing_ids:
        new_id = _gen_id()

    # Store "encrypted" payload (offline): base64 of secret with a prefix; never returned by list/get.
    secret_ciphertext = "enc_v1:" + base64.b64encode(secret.encode("utf-8")).decode("ascii")
    secret_last4 = secret[-4:] if len(secret) >= 4 else secret

    now = _now_iso()
    row = {
        "id": new_id,
        "name": name,
        "registry": reg,
        "username": username,
        "credential_type": credential_type,
        "secret_ciphertext": secret_ciphertext,
        "secret_last4": secret_last4,
        "status": "active",
        "last_validated_at": None,
        "deleted_at": None,
        "created_at": now,
        "updated_at": now,
    }
    cras.append(row)
    _save("container_registry_auths.json", cras)

    # Return metadata only (no secret_ciphertext)
    out = {k: v for k, v in row.items() if k not in ("secret_ciphertext",)}
    _append_log("success", None, new_id)
    return {"container_registry_auth": out, "meta": {"created_at": now, "latency_ms": int(max(0, (time.time() - t0) * 1000))}}

def delete_container_registry_auth(container_registry_auth_id, force=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0442000" if __import__("os").path.isdir("./environment_mix/0442000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    if not isinstance(container_registry_auth_id, str) or not container_registry_auth_id:
        return _err("VALIDATION_ERROR", "container_registry_auth_id is required and must be a string.", field="container_registry_auth_id")
    if not re.match(r"^cra_[0-9A-Z]{26}$", container_registry_auth_id):
        return _err("VALIDATION_ERROR", "container_registry_auth_id format is invalid.", field="container_registry_auth_id", pattern="^cra_[0-9A-Z]{26}$")
    if force is not None and not isinstance(force, bool):
        return _err("VALIDATION_ERROR", "force must be a boolean when provided.", field="force")
    force = bool(force) if force is not None else False

    cra = _load("container_registry_auths.json")
    pods = _load("pods.json")
    endpoints = _load("endpoints.json")

    idx = None
    for i, r in enumerate(cra):
        if isinstance(r, dict) and r.get("id") == container_registry_auth_id:
            idx = i
            break
    if idx is None:
        return _err("NOT_FOUND", "Container registry auth credential not found.", container_registry_auth_id=container_registry_auth_id)

    row = cra[idx]
    if row.get("deleted_at") is not None or row.get("status") == "deleted":
        # Idempotent delete: already deleted
        resp = {
            "id": row.get("id"),
            "object": "container_registry_auth",
            "deleted": True,
            "status": "deleted",
            "deleted_at": row.get("deleted_at"),
            "meta": {"latency_ms": int((time.time() - t0) * 1000)}
        }
        return resp

    # Check references from non-deleted pods/endpoints
    referencing = {"pods": [], "endpoints": []}
    for p in pods:
        if not isinstance(p, dict):
            continue
        if p.get("deleted_at") is None and p.get("container_registry_auth_id") == container_registry_auth_id:
            referencing["pods"].append(p.get("id"))
    for e in endpoints:
        if not isinstance(e, dict):
            continue
        if e.get("deleted_at") is None and e.get("container_registry_auth_id") == container_registry_auth_id:
            referencing["endpoints"].append(e.get("id"))

    if (referencing["pods"] or referencing["endpoints"]) and not force:
        return _err(
            "CONFLICT",
            "Cannot delete: credential is still referenced by pods/endpoints. Use force=true to null references then delete.",
            references=referencing
        )

    # If force, null references first (preserve referential integrity)
    mutated = False
    if force and (referencing["pods"] or referencing["endpoints"]):
        for p in pods:
            if isinstance(p, dict) and p.get("deleted_at") is None and p.get("container_registry_auth_id") == container_registry_auth_id:
                p["container_registry_auth_id"] = None
                p["updated_at"] = now
                mutated = True
        for e in endpoints:
            if isinstance(e, dict) and e.get("deleted_at") is None and e.get("container_registry_auth_id") == container_registry_auth_id:
                e["container_registry_auth_id"] = None
                e["updated_at"] = now
                mutated = True

    # Soft-delete the auth
    prev_status = row.get("status") or "active"
    allowed = {"active": ["revoked", "deleted"], "revoked": ["active", "deleted"], "deleted": []}
    if prev_status not in allowed or "deleted" not in allowed.get(prev_status, []):
        return _err("INVALID_TRANSITION", "Cannot transition container registry auth to 'deleted' from current status.", from_status=prev_status, to_status="deleted")

    row["status"] = "deleted"
    row["deleted_at"] = now
    row["updated_at"] = now
    cra[idx] = row

    _save("container_registry_auths.json", cra)
    if mutated:
        _save("pods.json", pods)
        _save("endpoints.json", endpoints)

    resp = {
        "id": container_registry_auth_id,
        "object": "container_registry_auth",
        "deleted": True,
        "status": "deleted",
        "deleted_at": now,
        "references_cleared": referencing if force else {"pods": [], "endpoints": []},
        "meta": {"latency_ms": int((time.time() - t0) * 1000)}
    }
    return resp
